// case insensitive lookup by object path, early out on the first hit
template <class T> T* findObjectByPath(const std::string& path) {
    if (path.empty() || !UObject::GObjObjects || !UObject::GObjObjects->GetData()) {
        return nullptr;
    }
    const std::string needle = toLowerStr(path);
    UObject** data = UObject::GObjObjects->GetData();
    const int count = (int)UObject::GObjObjects->Count();
    for (int i = 0; i < count; ++i) {
        UObject* obj = data[i];
        if (!obj || !obj->Class || !obj->IsA(T::StaticClass())) {
            continue;
        }
        if (toLowerStr(FStringToUtf8(obj->GetFullPath())) == needle) {
            return static_cast<T*>(obj);
        }
    }
    return nullptr;
}

// IsA on a UClass compares against the metaclass, so a class has to be walked
// from itself - same as UI::isActorClass
bool isPawnClass(UClass* cls) {
    for (UClass* s = cls; s; s = (UClass*)s->SuperField) {
        if (s == ABioPawn::StaticClass()) {
            return true;
        }
    }
    return false;
}

// LE1 has no SFXPawn, BioPawn is the root pawn class there
#ifdef SDK_TARGET_LE1
const char* const preferredPawnClasses[] = {"Class SFXGame.BioPawn"};
#else
const char* const preferredPawnClasses[] = {"Class SFXGame.BioPawn", "Class SFXGame.SFXPawn"};
#endif

// no IsChildOf in the SDK, walk SuperField
bool isSubclassOf(UClass* candidate, UClass* base) {
    for (UClass* s = candidate; s; s = (UClass*)s->SuperField) {
        if (s == base) {
            return true;
        }
    }
    return false;
}

int preferredClassRank(const std::string& name) {
    for (int i = 0; i < (int)(sizeof(preferredPawnClasses) / sizeof(preferredPawnClasses[0])); ++i) {
        if (name == preferredPawnClasses[i]) {
            return i;
        }
    }
    return 100;
}

void describeObject(std::ostream& ss, const char* label, UObject* obj) {
    ss << "    " << label << ": ";
    if (!obj) {
        ss << "NULL\n";
        return;
    }
    std::string className = "?";
    if (obj->Class) {
        className = FStringToUtf8(obj->Class->GetName());
    }
    ss << FStringToUtf8(obj->GetFullPath()) << " [" << className << "]";
    if (!isLiveObject(obj)) {
        ss << " (NOT LIVE)";
    }
    ss << "\n";
}

// the flags are patched across the call, so guard it
bool callSpawnGuarded(AActor* caller, UClass* cls, const SFXName& tag, const FVector& loc, const FRotator& rot, AActor* appearanceTemplate, AActor** out) {
    __try {
#ifdef SDK_TARGET_LE3
        *out = caller->Spawn(cls, nullptr, tag, loc, rot, appearanceTemplate, 1, 0);
#else
        *out = caller->Spawn(cls, nullptr, tag, loc, rot, appearanceTemplate, nullptr, 1, 0);
#endif
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        *out = nullptr;
        return false;
    }
    return true;
}

AActor* trySpawnClass(UClass* cls, AActor* caller, const FVector& loc, const FRotator& rot, AActor* appearanceTemplate) {
    const DWORD originalFlags = cls->ClassFlags;
    std::string callerClassName = "?";
    if (caller->Class) {
        callerClassName = FStringToUtf8(caller->Class->GetFullName());
    }
    {
        std::ostringstream pre;
        pre << "spawnNPC: trying '" << FStringToUtf8(cls->GetFullName()) << "' caller='" << FStringToUtf8(caller->GetName()) << "' callerClass='"
            << callerClassName << "' flagsBefore=0x" << std::hex << cls->ClassFlags << std::dec << " cdo=" << (cls->ClassDefaultObject ? "yes" : "NO")
            << " within='" << (cls->ClassWithin ? FStringToUtf8(cls->ClassWithin->GetFullName()) : "(none)") << "'";
        Logger->debug(pre.str());
    }
    // LE2's Spawn enforces the Placeable flag. LE1's values are unverified (util.h)
    // and a wrong bit leaves the class mislabelled, so LE1 spawns unmodified
#ifndef SDK_TARGET_LE1
    cls->ClassFlags |= CLASS_Placeable;
    cls->ClassFlags &= ~CLASS_NotPlaceable;
#endif
    AActor* spawned = nullptr;
    const bool threw = !callSpawnGuarded(caller, cls, SFXName(), loc, rot, appearanceTemplate, &spawned);
    cls->ClassFlags = originalFlags;
    std::string outcome = "refused (null)";
    if (threw) {
        outcome = "refused (Spawn threw)";
    }
    if (spawned) {
        outcome = "spawned as '" + FStringToUtf8(spawned->GetName()) + "'";
    }
    std::string templateName = "(none)";
    if (appearanceTemplate) {
        templateName = FStringToUtf8(appearanceTemplate->GetFullPath());
    }

    std::ostringstream post;
    post << "spawnNPC: '" << FStringToUtf8(cls->GetFullName()) << "' -> " << outcome << ", template=" << templateName << ", flags restored to 0x" << std::hex
         << cls->ClassFlags;
    Logger->debug(post.str());
    return spawned;
}

int classDepth(UClass* cls) {
    int depth = 0;
    for (UClass* s = cls; s && s != AActor::StaticClass(); s = (UClass*)s->SuperField) {
        ++depth;
    }
    return depth;
}

bool isSameOrSubclassOf(UClass* cls, UClass* base) {
    for (UClass* s = cls; s; s = (UClass*)s->SuperField) {
        if (s == base) {
            return true;
        }
    }
    return false;
}

// never use a player pawn as a Spawn template, its properties carry the live
// player's camera and controller handles, and it matches every pawn query
static bool isUsableSpawnTemplate(AActor* candidate) {
    if (!candidate || !isLiveObject(candidate) || !candidate->Class) {
        return false;
    }
    const std::string clsName = FStringToUtf8(candidate->Class->GetFullName());
    if (clsName.find("Player") != std::string::npos) {
        return false;
    }
    if (APlayerController* pc = findFirstOf<APlayerController>()) {
        if (isLiveObject(pc)) {
            if (candidate == static_cast<AActor*>(pc) || candidate == pc->Pawn || candidate == pc->PlayerCamera) {
                return false;
            }
        }
    }
    return true;
}

std::vector<UClass*> buildSpawnCandidates(UClass* cls) {
    std::vector<UClass*> candidates;
    for (UClass* s = cls; s && s != AActor::StaticClass(); s = (UClass*)s->SuperField) {
        candidates.push_back(s);
    }

    std::vector<UClass*> descendants;
    forEachOf<UClass>([&](UClass* candidate) {
        if (!candidate || candidate == cls || (candidate->ClassFlags & CLASS_Abstract)) {
            return;
        }
        // a second player pawn owns the camera and input, never make one
        if (FStringToUtf8(candidate->GetFullName()).find("Player") != std::string::npos) {
            return;
        }
        if (isSameOrSubclassOf(candidate, cls)) {
            descendants.push_back(candidate);
        }
    });

    std::sort(descendants.begin(), descendants.end(), [](UClass* a, UClass* b) {
        // the shipped classes live in the game's pawn package, match on the suffix
        // so it works for every game
        auto isGameNpc = [](UClass* c) {
            if (!c->Outer) {
                return false;
            }
            const std::string pkg = FStringToUtf8(c->Outer->GetName());
            return pkg.size() > 5 && pkg.compare(pkg.size() - 5, 5, "Pawns") == 0;
        };
        bool gameA = isGameNpc(a);
        bool gameB = isGameNpc(b);
        if (gameA != gameB) {
            return gameA; // the pawn packages first
        }
        int depthA = classDepth(a);
        int depthB = classDepth(b);
        if (depthA != depthB) {
            return depthA > depthB; // most derived first
        }
        return FStringToUtf8(a->GetFullName()) < FStringToUtf8(b->GetFullName());
    });

    for (UClass* d : descendants) {
        if (candidates.size() >= 8) {
            break;
        }
        candidates.push_back(d);
    }
    return candidates;
}

UMaterialInterface* findMaterialByPath(const std::string& path) {
    if (path.empty() || !UObject::GObjObjects || !UObject::GObjObjects->GetData()) {
        return nullptr;
    }
    const std::string needle = toLowerStr(path);
    UObject** data = UObject::GObjObjects->GetData();
    const int count = (int)UObject::GObjObjects->Count();
    for (int i = 0; i < count; ++i) {
        UObject* obj = data[i];
        if (!obj || !obj->Class || !obj->IsA(UMaterialInterface::StaticClass())) {
            continue;
        }
        if (toLowerStr(FStringToUtf8(obj->GetFullPath())) == needle) {
            return static_cast<UMaterialInterface*>(obj);
        }
    }
    return nullptr;
}

ABioPawn* resolvePawn(const std::string& pawnName) {
    AActor* actor = Application::instance().engine().findActorByName(pawnName);
    if (!actor || !actor->IsA(ABioPawn::StaticClass()) || !isLiveObject(actor)) {
        Logger->debug("NPC live edit: pawn '" + pawnName + "' no longer exists or is not an ABioPawn");
        return nullptr;
    }
    return static_cast<ABioPawn*>(actor);
}

// the pawn caches per mesh material instances, they still point at the old
// mesh's sections until rebuilt. no rebuild on LE3
void rebuildPawnMaterials(ABioPawn* pawn) {
#ifdef SDK_TARGET_LE2
    pawn->ClearMaterialInstances();
    pawn->RefreshMaterialInstances();
#else
    (void)pawn;
#endif
}

void pushMorphMaterialOverrides(UBioMorphFace* morph, ABioPawn* pawn) {
#ifdef SDK_TARGET_LE1
    // no ApplyMaterialOverrides on LE1, ApplyMaterialParameters takes the same
    // UBioMaterialOverride
    if (morph && morph->m_oMaterialOverrides) {
        pawn->ApplyMaterialParameters(morph->m_oMaterialOverrides);
    }
#elif defined(SDK_TARGET_LE2)
    morph->ApplyMaterialOverridesToPawn(pawn);
#else
    morph->ApplyMaterialOverridesToActor(pawn);
#endif
}

