const char* NPCManager::slotLabelKey(int slot) {
    switch (slot) {
        case PAWN_SLOT_BODY:
            return "ui.npcs_table.body_mesh";
        case PAWN_SLOT_HEAD:
            return "ui.npcs_table.head_mesh";
        case PAWN_SLOT_HAIR:
            return "ui.npcs_table.hair_mesh";
        case PAWN_SLOT_HEADGEAR:
            return "ui.npcs_table.headgear_mesh";
        case PAWN_SLOT_VISOR:
            return "ui.npcs_table.visor_mesh";
        case PAWN_SLOT_FACEPLATE:
            return "ui.npcs_table.faceplate_mesh";
        default:
            return "ui.npcs_table.slot";
    }
}

UBioMorphFace* NPCManager::morphHeadFor(ABioPawn* pawn) {
    if (!pawn) {
        return nullptr;
    }
#ifdef SDK_TARGET_LE1
    std::lock_guard<std::mutex> lock(stateMtx);
    auto it = morphHeadsByPawn.find(FStringToUtf8(pawn->GetName()));
    return it == morphHeadsByPawn.end() ? nullptr : it->second;
#else
    return pawn->MorphHead;
#endif
}

void NPCManager::setMorphHeadFor(ABioPawn* pawn, UBioMorphFace* morph) {
    if (!pawn) {
        return;
    }
#ifdef SDK_TARGET_LE1
    std::lock_guard<std::mutex> lock(stateMtx);
    const std::string key = FStringToUtf8(pawn->GetName());
    if (morph) {
        morphHeadsByPawn[key] = morph;
    } else {
        morphHeadsByPawn.erase(key);
    }
#else
    pawn->MorphHead = morph;
#endif
}

void NPCManager::forgetMorphHead(ABioPawn* pawn) {
    if (!pawn) {
        return;
    }
#ifdef SDK_TARGET_LE1
    std::lock_guard<std::mutex> lock(stateMtx);
    morphHeadsByPawn.erase(FStringToUtf8(pawn->GetName()));
#else
    pawn->MorphHead = nullptr;
#endif
}

USkeletalMeshComponent* NPCManager::slotComponent(ABioPawn* pawn, int slot) {
    if (!pawn) {
        return nullptr;
    }
    switch (slot) {
        case PAWN_SLOT_BODY:
            return pawn->Mesh;
        case PAWN_SLOT_HEAD:
#ifdef SDK_TARGET_LE1
            return pawn->m_oHeadMesh;
#else
            return pawn->HeadMesh;
#endif
        case PAWN_SLOT_HAIR:
            return pawn->m_oHairMesh;
        case PAWN_SLOT_HEADGEAR:
            return pawn->m_oHeadGearMesh;
        case PAWN_SLOT_VISOR:
            return pawn->m_oVisorMesh;
        case PAWN_SLOT_FACEPLATE:
            return pawn->m_oFacePlateMesh;
        default:
            return nullptr;
    }
}

#pragma region // asset collection

void NPCManager::applyAssets() {
    std::lock_guard<std::mutex> lock(stateMtx);
    assetsToApply = true;
}

// harvest the game's own choices rather than guessing from names
void NPCManager::collectKnownGoodMeshes() {
    for (int slot = 0; slot < PAWN_SLOT_COUNT; ++slot) {
        validMeshPaths[slot].clear();
    }

    auto note = [this](int slot, USkeletalMesh* mesh) {
        if (!mesh || slot < 0 || slot >= PAWN_SLOT_COUNT) {
            return;
        }
        std::string lower = toLowerStr(FStringToUtf8(mesh->GetFullPath()));
        std::vector<std::string>& known = validMeshPaths[slot];
        if (std::find(known.begin(), known.end(), lower) == known.end()) {
            known.push_back(lower);
        }
    };

    forEachOf<ABioPawn>([&](ABioPawn* pawn) {
        if (!pawn || !isLiveObject(pawn)) {
            return;
        }
        for (int slot = 0; slot < PAWN_SLOT_COUNT; ++slot) {
            USkeletalMeshComponent* comp = slotComponent(pawn, slot);
            if (comp) {
                note(slot, comp->SkeletalMesh);
            }
        }
    });

    forEachOf<UBioMorphFace>([&](UBioMorphFace* morph) {
        if (!morph) {
            return;
        }
        note(PAWN_SLOT_HEAD, morph->m_oBaseHead);
        note(PAWN_SLOT_HAIR, morph->m_oHairMesh);
    });

    std::ostringstream ss;
    ss << "collectKnownGoodMeshes:";
    for (int slot = 0; slot < PAWN_SLOT_COUNT; ++slot) {
        ss << " " << t(slotLabelKey(slot)) << "=" << validMeshPaths[slot].size();
    }
    Logger->debug(ss.str());
}

bool NPCManager::isKnownGoodForSlot(int slot, const std::string& pathLower) const {
    if (slot < 0 || slot >= PAWN_SLOT_COUNT) {
        return true;
    }
    const std::vector<std::string>& known = validMeshPaths[slot];
    return std::find(known.begin(), known.end(), pathLower) != known.end();
}

void NPCManager::collectAssets(bool force) {
    ZoneScopedN("NPC::collectAssets");
    {
        std::lock_guard<std::mutex> lock(stateMtx);
        if (!force && assetsCollected && !assetsToApply) {
            return;
        }
        assetsCollected = true;
        assetsToApply = false;
    }

    pawnClasses.clear();
    pawnClassesLower.clear();
    skeletalMeshes.clear();
    skeletalMeshesLower.clear();
    skeletalMeshBones.clear();
    morphFaces.clear();
    morphFacesLower.clear();
    materialAssets.clear();
    materialAssetsLower.clear();
#ifndef SDK_TARGET_LE3
    crustTemplates.clear();
    crustTemplatesLower.clear();
#endif

    if (!UObject::GObjObjects) {
        return;
    }

    forEachOf<UClass>([&](UClass* cls) {
        if (!isPawnClass(cls) || (cls->ClassFlags & CLASS_Abstract)) {
            return;
        }
        std::string full = FStringToUtf8(cls->GetFullName());
        if (std::find(pawnClasses.begin(), pawnClasses.end(), full) != pawnClasses.end()) {
            return;
        }
        pawnClasses.push_back(full);
    });

    std::sort(pawnClasses.begin(), pawnClasses.end(), [](const std::string& a, const std::string& b) {
        int ra = preferredClassRank(a);
        int rb = preferredClassRank(b);
        if (ra != rb) {
            return ra < rb;
        }
        return a < b;
    });
    pawnClassesLower.reserve(pawnClasses.size());
    residentPawnShortNamesLower.clear();
    residentPawnShortNamesLower.reserve(pawnClasses.size());
    for (const std::string& c : pawnClasses) {
        pawnClassesLower.push_back(toLowerStr(c));
        const size_t lastDot = c.rfind('.');
        residentPawnShortNamesLower.push_back(toLowerStr(lastDot == std::string::npos ? c : c.substr(lastDot + 1)));
    }

    forEachOf<USkeletalMesh>([&](USkeletalMesh* mesh) {
        if (!mesh) {
            return;
        }
        skeletalMeshes.push_back(FStringToUtf8(mesh->GetFullPath()));
        skeletalMeshesLower.push_back(toLowerStr(skeletalMeshes.back()));
        skeletalMeshBones.push_back(mesh->RefSkeleton.Count());
    });

    forEachOf<UBioMorphFace>([&](UBioMorphFace* morph) {
        if (!morph) {
            return;
        }
        morphFaces.push_back(FStringToUtf8(morph->GetFullPath()));
        morphFacesLower.push_back(toLowerStr(morphFaces.back()));
    });

    materialAssets.clear();
    materialAssetsLower.clear();
    forEachOf<UMaterialInterface>([&](UMaterialInterface* material) {
        if (!material) {
            return;
        }
        materialAssets.push_back(FStringToUtf8(material->GetFullPath()));
        materialAssetsLower.push_back(toLowerStr(materialAssets.back()));
    });

#ifndef SDK_TARGET_LE3
    forEachOf<UBioVFXTemplate>([&](UBioVFXTemplate* vfx) {
        if (!vfx || !vfx->bIsInitialized) {
            return;
        }
        crustTemplates.push_back(FStringToUtf8(vfx->GetFullPath()));
        crustTemplatesLower.push_back(toLowerStr(crustTemplates.back()));
    });
#endif

    std::ostringstream ss;
    ss << "collectAssets: " << pawnClasses.size() << " pawn classes, " << skeletalMeshes.size() << " skeletal meshes, " << morphFaces.size() << " morph faces";
    Logger->debug(ss.str());

    collectKnownGoodMeshes();
    rebuildResidentPawns();
}

#pragma endregion

#pragma region // applying

bool NPCManager::applySlot(ABioPawn* pawn, int slot, USkeletalMesh* mesh) {
    USkeletalMeshComponent* comp = slotComponent(pawn, slot);
    if (!comp) {
        std::ostringstream ss;
        ss << "applySlot: '" << FStringToUtf8(pawn->GetName()) << "' has no component for slot " << slot << " (" << t(slotLabelKey(slot)) << "), skipping";
        Logger->debug(ss.str());
        return false;
    }

    int oldBones = 0;
    if (comp->SkeletalMesh) {
        oldBones = comp->SkeletalMesh->RefSkeleton.Count();
    }
    const int newBones = mesh ? mesh->RefSkeleton.Count() : 0;

#ifdef SDK_TARGET_LE1
    // LE1 has no per-character pawn classes, so every pawn is built for one bone
    // topology. resizing a component leaves the pose state on the old count and the
    // game faults on it, so refuse the swap
    if (mesh && oldBones > 0 && newBones > 0) {
        const int worst = (std::max)(oldBones, newBones);
        const int diff = worst - (std::min)(oldBones, newBones);
        if ((diff * 100) / worst > 20) {
            std::ostringstream ss;
            ss << "applySlot: '" << FStringToUtf8(pawn->GetName()) << "' slot " << slot << " (" << t(slotLabelKey(slot)) << ") needs " << newBones
               << " bones but the pawn's component has " << oldBones << " - refused, because LE1 cannot spawn a pawn built for this skeleton";
            Logger->debug(ss.str());
            return false;
        }
    }
#endif

    comp->SetSkeletalMesh(mesh, 0, 0);
    comp->ForceSkelUpdate();

    rebuildPawnMaterials(pawn);
    reapplyMaterialOverrides(pawn);

    if (slot == PAWN_SLOT_HEAD) {
        rememberBaseHead(pawn, mesh);
    }

    std::ostringstream ss;
    std::string meshName = "(cleared)";
    if (mesh) {
        meshName = FStringToUtf8(mesh->GetFullPath());
    }
    ss << "applySlot: '" << FStringToUtf8(pawn->GetName()) << "' slot " << slot << " -> " << meshName << " bones=" << newBones
       << " atoms=" << comp->LocalAtoms.Count();
    Logger->debug(ss.str());

    if (oldBones > 0 && newBones > 0) {
        // windows.h defines min/max as macros
        const int worst = (std::max)(oldBones, newBones);
        const int diff = worst - (std::min)(oldBones, newBones);
        if ((diff * 100) / worst > 40) {
            std::ostringstream warn;
            warn << "applySlot: slot " << slot << " (" << t(slotLabelKey(slot)) << ") bone count changed from " << oldBones << " to " << newBones
                 << ", this mesh probably does not belong in that slot";
            Logger->debug(warn.str());
            char warnBuf[512];
            snprintf(warnBuf, sizeof(warnBuf), t("ui.npcs_table.bones_mismatch"), oldBones, newBones, t(slotLabelKey(slot)));
            Application::instance().ui().toastManager.addToastNotification(warnBuf, ToastTypeWarning, 4.0);
        }
    }
    return true;
}

USkeletalMesh* NPCManager::plainHeadMeshFor(ABioPawn* pawn) const {
    USkeletalMeshComponent* head = slotComponent(pawn, PAWN_SLOT_HEAD);
    if (!head || !head->SkeletalMesh) {
        return nullptr;
    }
    std::lock_guard<std::mutex> lock(stateMtx);
    auto it = baseHeadByPawn.find(FStringToUtf8(pawn->GetName()));
    if (it != baseHeadByPawn.end() && it->second && isLiveObject(it->second)) {
        return it->second;
    }
#ifndef SDK_TARGET_LE1
    if (head->SkeletalMesh->IsA(USFXCompositeSkeletalMesh::StaticClass())) {
        return nullptr;
    }
#endif
    return head->SkeletalMesh;
}

void NPCManager::rememberBaseHead(ABioPawn* pawn, USkeletalMesh* mesh) {
    if (!slotComponent(pawn, PAWN_SLOT_HEAD)) {
        return;
    }
    std::lock_guard<std::mutex> lock(stateMtx);
#ifndef SDK_TARGET_LE1
    if (!mesh || mesh->IsA(USFXCompositeSkeletalMesh::StaticClass())) {
        return;
    }
#endif
    if (mesh) {
        baseHeadByPawn[FStringToUtf8(pawn->GetName())] = mesh;
    }
}

// no StaticConstructObject resolver in the SDK, so a missing component cannot be
// built. the game composes the extras into the head instead.
bool NPCManager::applyCompositeAddons(ABioPawn* pawn, const std::vector<USkeletalMesh*>& addons) {
#ifdef SDK_TARGET_LE2
    if (addons.empty()) {
        return false;
    }
    USkeletalMeshComponent* headComp = slotComponent(pawn, PAWN_SLOT_HEAD);
    if (!headComp) {
        Logger->debug("applyCompositeAddons: pawn has no head component");
        return false;
    }
    USkeletalMesh* base = plainHeadMeshFor(pawn);
    if (!base) {
        Logger->debug("applyCompositeAddons: no plain head mesh to merge into, the head is already a composite");
        return false;
    }

    TArray<USkeletalMesh*> extra;
    for (USkeletalMesh* addon : addons) {
        extra.Add(addon);
    }
    USFXCompositeSkeletalMesh* composite = pawn->MergeMeshes(base, extra, headComp);
    if (!composite) {
        Logger->debug("applyCompositeAddons: MergeMeshes returned null");
        return false;
    }

    headComp->SetSkeletalMesh(composite, 0, 0);
    headComp->ForceSkelUpdate();
    rebuildPawnMaterials(pawn);
    reapplyMaterialOverrides(pawn);
    reapplyHeadMesh(pawn);

    std::ostringstream ss;
    ss << "applyCompositeAddons: '" << FStringToUtf8(pawn->GetName()) << "' base=" << FStringToUtf8(base->GetFullPath()) << " +";
    for (USkeletalMesh* addon : addons) {
        ss << " " << FStringToUtf8(addon->GetName());
    }
    ss << " -> " << FStringToUtf8(composite->GetFullPath()) << " bones=" << composite->RefSkeleton.Count() << " sources=" << composite->SourceMeshNames.Count()
       << " overrides=" << composite->OverrideInfo.Count() << " materials=" << composite->Materials.Count();
    for (int i = 0; i < (int)composite->SourceMeshNames.Count(); ++i) {
        ss << " [" << i << "]=" << FStringToUtf8(composite->SourceMeshNames.GetData()[i]);
    }
    // the component may quietly ignore it, so confirm
    ss << " | assigned=" << (headComp->SkeletalMesh == composite ? "yes" : "NO") << " live=" << (isLiveObject(composite) ? "yes" : "NO");
    Logger->debug(ss.str());
    return true;
#else
    Logger->debug("applyCompositeAddons: MergeMeshes is not available on this game's SDK");
    (void)pawn;
    (void)addons;
    return false;
#endif
}

void NPCManager::applyMorphHead(ABioPawn* pawn, UBioMorphFace* morph) {
    setMorphHeadFor(pawn, morph);
    if (!morph) {
        Logger->debug("applyMorphHead: cleared MorphHead");
        return;
    }

    USkeletalMeshComponent* head = slotComponent(pawn, PAWN_SLOT_HEAD);
    if (head) {
        head->MorphSets.Clear();
        if (morph->m_oMorphTargetSet) {
            head->MorphSets.Add(morph->m_oMorphTargetSet);
        }
        head->InitMorphTargets();
    }

#ifdef SDK_TARGET_LE3
    morph->ApplyToActor(pawn);
    morph->ApplyMaterialOverridesToActor(pawn);
#elif defined(SDK_TARGET_LE1)
    // no ApplyMaterialOverrides on LE1, route through ApplyMaterialParameters
    pushMorphMaterialOverrides(morph, pawn);
#else
    morph->ApplyMaterialOverridesToPawn(pawn);
#endif

    if (!pawn->m_oHairMesh && morph->m_oHairMesh) {
        Logger->debug("applyMorphHead: '" + FStringToUtf8(pawn->GetName()) +
                      "' has no hair component, hair comes from the morph face: " + FStringToUtf8(morph->m_oHairMesh->GetFullPath()));
    }

    std::ostringstream ss;
    ss << "applyMorphHead: '" << FStringToUtf8(pawn->GetName()) << "' -> " << FStringToUtf8(morph->GetFullPath())
       << " baseHead=" << (morph->m_oBaseHead ? FStringToUtf8(morph->m_oBaseHead->GetName()) : "(none)") << " morphTargets=" << morph->m_aMorphFeatures.Count()
       << " headComp=" << (head ? "yes" : "NO");
    Logger->debug(ss.str());

    reapplyHeadMesh(pawn);
}

// the engine only binds a morph when the head mesh is set again, so hair and
// morph changes end with a head re apply. the face is vertex buffers, not
// parameters, so the probe below is what tells us if a write lands.
void NPCManager::logMorphBufferProbe(ABioPawn* pawn, const char* when) {
    UBioMorphFace* morph = morphHeadFor(pawn);
    if (!morph) {
        return;
    }
    std::ostringstream ss;
    ss << "morphBufferProbe[" << when << "]: '" << FStringToUtf8(pawn->GetName()) << "' morph=" << FStringToUtf8(morph->GetFullPath())
       << " buffers=" << morph->GetNumVertexBuffers();
    for (int buffer = 0; buffer < morph->GetNumVertexBuffers() && buffer < 4; ++buffer) {
        const int verts = morph->GetNumVerts(buffer);
        double sum = 0.0;
        int sampled = 0;
        const int step = verts > 16 ? verts / 16 : 1;
        for (int v = 0; v < verts && sampled < 16; v += step) {
            FVector p = morph->GetPosition(buffer, v);
            sum += p.X + p.Y * 3.0 + p.Z * 7.0;
            ++sampled;
        }
        ss << " | buf" << buffer << " verts=" << verts << " fingerprint=" << sum;
    }
    USkeletalMeshComponent* head = slotComponent(pawn, PAWN_SLOT_HEAD);
    if (head) {
        ss << " | headMorphSets=" << head->MorphSets.Count() << " activeMorphs=" << head->ActiveMorphs.Count()
           << " headMesh=" << (head->SkeletalMesh ? FStringToUtf8(head->SkeletalMesh->GetName()) : "(none)");
    }
    ss << " | feature0=" << (morph->m_aMorphFeatures.Count() > 0 ? morph->m_aMorphFeatures.GetData()[0].Offset : -1.0f);
    Logger->debug(ss.str());
}

// offsets have to be in the object before ApplyMorph evaluates them
void NPCManager::applyMorphToPawn(ABioPawn* pawn) {
    UBioMorphFace* morph = morphHeadFor(pawn);
    if (!morph) {
        return;
    }
    USkeletalMeshComponent* head = slotComponent(pawn, PAWN_SLOT_HEAD);

#ifdef SDK_TARGET_LE3
    morph->ApplyMorph();
    morph->ApplyToActor(pawn);
    if (head) {
        morph->ApplyMesh(head->SkeletalMesh, head);
    }
#else
    pushMorphMaterialOverrides(morph, pawn);
#endif
    refreshMorphBuffers(morph);

    if (head) {
        head->ForceSkelUpdate();
    }

    std::ostringstream ss;
    ss << "applyMorphToPawn: '" << FStringToUtf8(pawn->GetName()) << "' morph=" << FStringToUtf8(morph->GetFullPath())
       << " features=" << morph->m_aMorphFeatures.Count() << " buffers=" << morph->m_aVertexBuffers.Count()
       << " head=" << (head && head->SkeletalMesh ? FStringToUtf8(head->SkeletalMesh->GetName()) : "(none)");
    for (int i = 0; i < (int)morph->m_aMorphFeatures.Count() && i < 8; ++i) {
        const char* name = morph->m_aMorphFeatures.GetData()[i].sFeatureName.GetName();
        ss << " [" << (name ? name : "?") << "=" << morph->m_aMorphFeatures.GetData()[i].Offset << "]";
    }
    Logger->debug(ss.str());
}

void NPCManager::reapplyHeadMesh(ABioPawn* pawn) {
    USkeletalMeshComponent* head = slotComponent(pawn, PAWN_SLOT_HEAD);
    if (!head || !head->SkeletalMesh) {
        return;
    }
    USkeletalMesh* current = head->SkeletalMesh;
    head->SetSkeletalMesh(current, 0, 0);
    head->ForceSkelUpdate();

    UBioMorphFace* morph = morphHeadFor(pawn);
    if (morph) {
        head->MorphSets.Clear();
        if (morph->m_oMorphTargetSet) {
            head->MorphSets.Add(morph->m_oMorphTargetSet);
        }
        head->InitMorphTargets();
        applyMorphToPawn(pawn);
    }

    rebuildPawnMaterials(pawn);
    reapplyMaterialOverrides(pawn);

    std::ostringstream ss;
    ss << "reapplyHeadMesh: '" << FStringToUtf8(pawn->GetName()) << "' head=" << FStringToUtf8(current->GetFullPath())
       << " bones=" << current->RefSkeleton.Count() << " atoms=" << head->LocalAtoms.Count()
       << " morph=" << (morph ? FStringToUtf8(morph->GetFullPath()) : "(none)");
    Logger->debug(ss.str());
}

void NPCManager::refreshMorphBuffers(UBioMorphFace* morph) {
    if (!morph) {
        return;
    }
    const int buffers = (int)morph->m_aVertexBuffers.Count();
    TArray<int> indices;
    for (int i = 0; i < buffers; ++i) {
        indices.Add(i);
    }
    morph->RefreshBuffers(indices);
    Logger->debug("refreshMorphBuffers: '" + FStringToUtf8(morph->GetFullPath()) + "' refreshed " + std::to_string(buffers) + " buffers");
}

void NPCManager::applyMorphColor(const std::string& pawnName, int colorIndex, const FLinearColor& color) {
    withPawn(pawnName, [this, colorIndex, color](ABioPawn* pawn) {
        UBioMorphFace* morph = morphHeadFor(pawn);
        if (!morph || !morph->m_oMaterialOverrides) {
            return;
        }
        TArray<FColorParameter>* overrides = &morph->m_oMaterialOverrides->m_aColorOverrides;
        if (colorIndex < 0 || colorIndex >= (int)overrides->Count()) {
            return;
        }
        FColorParameter& parameter = overrides->GetData()[colorIndex];
        const FLinearColor previous = parameter.cValue;
        parameter.cValue = color;
        pushMorphMaterialOverrides(morph, pawn);
        const char* parameterName = parameter.nName.GetName();
        std::ostringstream ss;
        ss << "applyMorphColor: '" << FStringToUtf8(morph->GetFullPath()) << "' [" << colorIndex << "] " << (parameterName ? parameterName : "?") << " r"
           << previous.R << "/" << color.R << " g" << previous.G << "/" << color.G << " b" << previous.B << "/" << color.B
           << " readback=" << parameter.cValue.R;
        Logger->debug(ss.str());
    });
}

void NPCManager::reapplyMorphHead(const std::string& pawnName) {
    withPawn(pawnName, [this](ABioPawn* pawn) {
        UBioMorphFace* morph = morphHeadFor(pawn);
        if (!morph) {
            return;
        }
        USkeletalMeshComponent* head = slotComponent(pawn, PAWN_SLOT_HEAD);
        if (head) {
            head->MorphSets.Clear();
            if (morph->m_oMorphTargetSet) {
                head->MorphSets.Add(morph->m_oMorphTargetSet);
            }
            head->InitMorphTargets();
        }
        pushMorphMaterialOverrides(morph, pawn);
        refreshMorphBuffers(morph);
        if (head) {
            head->ForceSkelUpdate();
        }
        Logger->debug("reapplyMorphHead: re-applied " + FStringToUtf8(morph->GetFullPath()));
    });
}

#ifndef SDK_TARGET_LE3
void NPCManager::applyLifeCrust(ABioPawn* pawn, const std::string& templateName, float lifeTime) {
    if (templateName.empty()) {
        pawn->m_LifeCrust = nullptr;
        Logger->debug("applyLifeCrust: cleared m_LifeCrust");
        return;
    }

    UBioVFXTemplate* vfxTemplate = findVFXTemplateByPath(templateName);
    if (!vfxTemplate) {
        char failBuf[512];
        snprintf(failBuf, sizeof(failBuf), t("ui.npcs_table.crust_not_found"), templateName.c_str());
        Application::instance().ui().toastManager.addToastNotification(failBuf, ToastTypeError, 3.0);
        return;
    }

    ABioVisualEffect* donor = findFirstOf<ABioVisualEffect>();
    if (!donor) {
        ABioWorldInfo* worldInfo = findFirstOf<ABioWorldInfo>();
        if (worldInfo) {
            UBioVisualEffectPool* pool = worldInfo->GetVFXPool(vfxTemplate);
            if (pool) {
                donor = pool->GetEffect();
            }
        }
    }
    if (!isLiveObject(donor)) {
        Logger->debug("applyLifeCrust: no donor effect available for " + templateName);
        char noDonorBuf[512];
        snprintf(noDonorBuf, sizeof(noDonorBuf), t("ui.npcs_table.crust_no_donor"), FStringToUtf8(vfxTemplate->GetName()).c_str());
        Application::instance().ui().toastManager.addToastNotification(noDonorBuf, ToastTypeError, 3.0);
        return;
    }

    ABioVisualEffect* effect = donor->CreateCrustEffect(vfxTemplate, pawn, lifeTime, 0);
    if (!effect) {
        char failBuf[512];
        snprintf(failBuf, sizeof(failBuf), t("ui.npcs_table.crust_failed"), FStringToUtf8(vfxTemplate->GetName()).c_str());
        Application::instance().ui().toastManager.addToastNotification(failBuf, ToastTypeError, 3.0);
        return;
    }

    pawn->m_LifeCrust = effect;

    std::ostringstream ss;
    ss << "applyLifeCrust: '" << FStringToUtf8(pawn->GetName()) << "' -> " << FStringToUtf8(vfxTemplate->GetFullPath())
       << " effect=" << FStringToUtf8(effect->GetName()) << " lifeTime=" << lifeTime;
    Logger->debug(ss.str());

    char okBuf[512];
    snprintf(okBuf, sizeof(okBuf), t("ui.npcs_table.crust_applied"), FStringToUtf8(vfxTemplate->GetName()).c_str());
    Application::instance().ui().toastManager.addToastNotification(okBuf, ToastTypeSuccess, 2.0);
}
#endif

void NPCManager::applySpawnConfig(ABioPawn* pawn, const PawnSpawnConfig& config) {
    // body first, the head and gear hang off it. plain SFXGame.BioPawn has no
    // head gear / visor / face plate component, so report what we could not apply
    std::string missing;
    auto noteMissing = [this, &missing](int slot, bool applied) {
        if (applied) {
            return;
        }
        if (!missing.empty()) {
            missing += ", ";
        }
        missing += t(slotLabelKey(slot));
    };
    std::string skipped;
    auto noteSkipped = [this, &skipped](const std::string& path) {
        Logger->debug("applySpawnConfig: requested asset no longer exists, leaving that slot alone: " + path);
        if (!skipped.empty()) {
            skipped += ", ";
        }
        skipped += path;
    };

    if (!config.assets[PAWN_SLOT_BODY].empty()) {
        USkeletalMesh* body = findSkeletalMeshByPath(config.assets[PAWN_SLOT_BODY]);
        if (body) {
            noteMissing(PAWN_SLOT_BODY, applySlot(pawn, PAWN_SLOT_BODY, body));
        } else {
            // never pass nullptr, that strips the pawn's own body mesh
            noteSkipped(config.assets[PAWN_SLOT_BODY]);
        }
    }

    UBioMorphFace* morph = nullptr;
    if (!config.morphHead.empty()) {
        morph = findMorphHeadByPath(config.morphHead);
    }
    USkeletalMesh* head = nullptr;
    if (!config.assets[PAWN_SLOT_HEAD].empty()) {
        head = findSkeletalMeshByPath(config.assets[PAWN_SLOT_HEAD]);
    }
    if (morph && !head) {
        head = morph->m_oBaseHead;
    }
    if (head) {
        noteMissing(PAWN_SLOT_HEAD, applySlot(pawn, PAWN_SLOT_HEAD, head));
    } else if (!config.assets[PAWN_SLOT_HEAD].empty()) {
        noteSkipped(config.assets[PAWN_SLOT_HEAD]);
    }
    if (morph) {
        applyMorphHead(pawn, morph);
        if (config.assets[PAWN_SLOT_HAIR].empty() && morph->m_oHairMesh) {
            noteMissing(PAWN_SLOT_HAIR, applySlot(pawn, PAWN_SLOT_HAIR, morph->m_oHairMesh));
        }
    }

    for (int slot = PAWN_SLOT_HAIR; slot < PAWN_SLOT_COUNT; ++slot) {
        if (config.assets[slot].empty()) {
            continue;
        }
        USkeletalMesh* mesh = findSkeletalMeshByPath(config.assets[slot]);
        if (!mesh) {
            noteSkipped(config.assets[slot]);
            continue;
        }
        noteMissing(slot, applySlot(pawn, slot, mesh));
    }

#ifndef SDK_TARGET_LE3
    if (!config.lifeCrust.empty()) {
        applyLifeCrust(pawn, config.lifeCrust, config.lifeCrustLifeTime);
    }
#endif

    Logger->debug("applySpawnConfig: done");
    if (!missing.empty()) {
        char warnBuf[512];
        snprintf(warnBuf, sizeof(warnBuf), t("ui.npcs_table.no_component_for"), missing.c_str());
        Application::instance().ui().toastManager.addToastNotification(warnBuf, ToastTypeWarning, 4.0);
    }
    if (!skipped.empty()) {
        char skipBuf[512];
        snprintf(skipBuf, sizeof(skipBuf), t("ui.npcs_table.slot_unchanged"), skipped.c_str());
        Application::instance().ui().toastManager.addToastNotification(skipBuf, ToastTypeWarning, 4.0);
    }
}

void NPCManager::spawnNPC(const PawnSpawnConfig& config, const Transform& spawnTransform) {
    if (!GWorld || !*GWorld) {
        Logger->debug("spawnNPC: GWorld is null");
        Application::instance().ui().toastManager.addToastNotification(t("ui.npcs_table.failed_no_world"), ToastTypeError, 3.0);
        return;
    }
    if (config.classFullName.empty()) {
        Application::instance().ui().toastManager.addToastNotification(t("ui.npcs_table.failed_no_class"), ToastTypeError, 3.0);
        return;
    }

    std::wstring className = toWString(config.classFullName);
    std::wstring wanted = (className.find(L"Class ") == std::wstring::npos) ? (L"Class " + className) : className;
    UClass* cls = UObject::FindClass(wanted.c_str());
    if (!cls) {
        cls = UObject::FindClass(className.c_str());
    }
    if (!cls) {
        char failBuf[512];
        snprintf(failBuf, sizeof(failBuf), t("ui.spawn_table.failed_class_not_found"), config.classFullName.c_str());
        Application::instance().ui().toastManager.addToastNotification(failBuf, ToastTypeError, 4.0);
        return;
    }
    if (cls->ClassFlags & CLASS_Abstract) {
        char abstractBuf[512];
        snprintf(abstractBuf, sizeof(abstractBuf), t("ui.spawn_table.failed_class_abstract"), config.classFullName.c_str());
        Application::instance().ui().toastManager.addToastNotification(abstractBuf, ToastTypeError, 3.0);
        return;
    }

    auto usableCaller = [](AActor* candidate) {
        if (!candidate || !isLiveObject(candidate)) {
            return false;
        }
        return FStringToUtf8(candidate->GetName()).rfind("Default__", 0) != 0;
    };
    // spawn from a pawn first, Spawning from the world info overflows LE1's stack
    AActor* caller = nullptr;
    AActor* const candidates[3] = {Application::instance().engine().findActorByName(""), static_cast<AActor*>(findFirstOf<APlayerController>()),
                                   static_cast<AActor*>(findFirstOf<ABioWorldInfo>())};
    for (AActor* candidate : candidates) {
        if (usableCaller(candidate)) {
            caller = candidate;
            break;
        }
    }
    if (caller) {
        Logger->debug("spawnNPC: spawning from '" + FStringToUtf8(caller->GetName()) + "' class '" + FStringToUtf8(caller->Class->GetFullName()) + "'");
    }
    if (!caller) {
        Application::instance().ui().toastManager.addToastNotification(t("ui.spawn_table.failed_no_actor_available"), ToastTypeError, 3.0);
        return;
    }

    if (!config.classFullName.empty()) {
        std::ostringstream req;
        req << "spawnNPC: requested class='" << config.classFullName << "'";
        for (int slot = 0; slot < PAWN_SLOT_COUNT; ++slot) {
            req << " " << slot << "='" << config.assets[slot] << "'";
        }
        req << " morph='" << config.morphHead << "' crust='" << config.lifeCrust << "'";
        Logger->debug(req.str());
    }

    FVector loc;
    loc.X = spawnTransform.pos[0];
    loc.Y = spawnTransform.pos[1];
    loc.Z = spawnTransform.pos[2];
    FRotator rot;
    rot.Pitch = DegreesToUnrealRotationUnits(spawnTransform.rot[0]);
    rot.Yaw = DegreesToUnrealRotationUnits(spawnTransform.rot[1]);
    rot.Roll = DegreesToUnrealRotationUnits(spawnTransform.rot[2]);

    // the runtime refuses bare pawn classes and the game ships ready-made NPC
    // classes instead, so fall back to one of those rather than reporting failure
    AActor* appearanceTemplate = nullptr;
    AActor* spawned = nullptr;
    UClass* usedClass = nullptr;
    for (UClass* candidate : buildSpawnCandidates(cls)) {
        appearanceTemplate = findAppearanceTemplate(candidate);
        spawned = trySpawnClass(candidate, caller, loc, rot, appearanceTemplate);
        if (spawned) {
            usedClass = candidate;
            break;
        }
    }

    if (!spawned) {
        Logger->debug("spawnNPC: every candidate class was refused, dumping class diagnostics:");
        Logger->debug(Application::instance().engine().diagnoseClass(config.classFullName));
        char nullBuf[512];
        snprintf(nullBuf, sizeof(nullBuf), t("ui.spawn_table.failed_ret_null_class"), config.classFullName.c_str());
        Application::instance().ui().toastManager.addToastNotification(nullBuf, ToastTypeError, 4.0);
        return;
    }
    std::string usedClassName = config.classFullName;
    if (usedClass != cls) {
        usedClassName = FStringToUtf8(usedClass->GetFullName());
        Logger->debug("spawnNPC: '" + config.classFullName + "' was refused, fell back to " + usedClassName);
        char fallbackBuf[512];
        snprintf(fallbackBuf, sizeof(fallbackBuf), t("ui.npcs_table.fell_back"), usedClassName.c_str(), config.classFullName.c_str());
        Application::instance().ui().toastManager.addToastNotification(fallbackBuf, ToastTypeWarning, 4.0);
    }
    if (!spawned->IsA(ABioPawn::StaticClass())) {
        char wrongBuf[512];
        snprintf(wrongBuf, sizeof(wrongBuf), t("ui.npcs_table.failed_not_a_pawn"), FStringToUtf8(spawned->GetFullName()).c_str());
        Application::instance().ui().toastManager.addToastNotification(wrongBuf, ToastTypeError, 4.0);
        Logger->debug("spawnNPC: spawned class is not an ABioPawn, destroying it again");
        spawned->Destroy();
        return;
    }

    ABioPawn* pawn = static_cast<ABioPawn*>(spawned);
    const std::string pawnName = FStringToUtf8(pawn->GetName());

    // pawns are commonly bNoDelete and Destroy() refuses those, clear it here
    pawn->bNoDelete = 0;
    pawn->bStatic = 0;
    pawn->bMovable = 1;

#ifdef SDK_TARGET_LE1
    // a runtime-spawned BioPawn gets an unsized collision cylinder and falls through
    if (UPrimitiveComponent* coll = pawn->CollisionComponent) {
        if (coll->IsA(UCylinderComponent::StaticClass())) {
            UCylinderComponent* cyl = static_cast<UCylinderComponent*>(coll);
            if (cyl->CollisionRadius <= 0.0f || cyl->CollisionHeight <= 0.0f) {
                std::ostringstream ss;
                ss << "pawnCollision: '" << FStringToUtf8(pawn->GetName()) << "' collision cylinder was r=" << cyl->CollisionRadius
                   << " h=" << cyl->CollisionHeight << ", sizing it to the UE3 pawn default (34/72)";
                Logger->debug(ss.str());
                cyl->SetCylinderSize(34.0f, 72.0f);
            }
        }
    }
#endif

    if (!spawnEmptyPawn && appearanceTemplate) {
        copyAppearanceFrom(pawn, static_cast<ABioPawn*>(appearanceTemplate));
    }

    if (spawnEmptyPawn) {
        Logger->debug("spawnNPC: spawnEmpty requested, stripping the body of '" + pawnName + "'");
        applySlot(pawn, PAWN_SLOT_BODY, nullptr);
    } else {
        applySpawnConfig(pawn, config);
    }

    // a pawn with no body cannot be posed or photographed, say so right away
    // rather than leaving the user staring at an invisible actor
    USkeletalMeshComponent* body = slotComponent(pawn, PAWN_SLOT_BODY);
    if (!body || !body->SkeletalMesh) {
        Logger->debug("spawnNPC: '" + pawnName + "' has no body mesh, nothing will be visible");
        Application::instance().ui().toastManager.addToastNotification(t("ui.npcs_table.failed_no_body"), ToastTypeError, 4.0);
    }

    Application::instance().engine().addSpawnedName(pawnName);
    {
        std::lock_guard<std::mutex> lock(stateMtx);
        if (std::find(knownSpawnable.begin(), knownSpawnable.end(), usedClassName) == knownSpawnable.end()) {
            knownSpawnable.push_back(usedClassName);
        }
    }
    {
        std::lock_guard<std::mutex> lock(pendingSelectMtx);
        pendingSelect = pawnName;
    }

    std::ostringstream ss;
    ss << "spawnNPC: spawned '" << usedClassName << "' as '" << pawnName << "' at (" << spawnTransform.pos[0] << "," << spawnTransform.pos[1] << ","
       << spawnTransform.pos[2] << ") via caller '" << FStringToUtf8(caller->GetName()) << "'";
    Logger->debug(ss.str());

    char okBuf[512];
    snprintf(okBuf, sizeof(okBuf), t("ui.npcs_table.spawned"), pawnName.c_str());
    Application::instance().ui().toastManager.addToastNotification(okBuf, ToastTypeSuccess, 2.0);
}

#pragma endregion

#pragma region // live edits

void NPCManager::applySlotToPawn(const std::string& pawnName, int slot, const std::string& assetName) {
    const std::vector<std::string> addonPaths = currentAddonPicks();

    withPawn(pawnName, [this, slot, assetName, addonPaths](ABioPawn* pawn) {
        USkeletalMesh* mesh = nullptr;
        if (!assetName.empty()) {
            mesh = findSkeletalMeshByPath(assetName);
        }
        if (!mesh && !assetName.empty()) {
            Logger->debug("NPC live edit: asset no longer exists, slot left unchanged: " + assetName);
            char skipBuf[512];
            snprintf(skipBuf, sizeof(skipBuf), t("ui.npcs_table.slot_unchanged"), assetName.c_str());
            Application::instance().ui().toastManager.addToastNotification(skipBuf, ToastTypeWarning, 3.0);
            return;
        }
        // a missing addon component is composed into the head instead, and
        // MergeMeshes is additive so every addon has to be supplied in one go. LE1
        // has no composites, those slots are real components there
#ifndef SDK_TARGET_LE1
        if (isAddonSlot(slot) && !slotComponent(pawn, slot)) {
            if (!mesh) {
                Logger->debug("NPC live edit: pawn has no component for slot " + std::to_string(slot) + ", nothing to clear");
                return;
            }
            if (!rebuildHeadComposite(pawn, addonPaths)) {
                char mergeBuf[512];
                snprintf(mergeBuf, sizeof(mergeBuf), t("ui.npcs_table.hair_merge_failed"), FStringToUtf8(mesh->GetName()).c_str());
                Application::instance().ui().toastManager.addToastNotification(mergeBuf, ToastTypeError, 4.0);
            }
            return;
        }
#endif
        applySlot(pawn, slot, mesh);
    });
}

// recompose the head from the plain head mesh plus every addon the user picked,
// so repeated picks replace each other instead of stacking
bool NPCManager::rebuildHeadComposite(ABioPawn* pawn, const std::vector<std::string>& addonPaths) {
    std::vector<USkeletalMesh*> addons;
    static const int addonSlots[] = {PAWN_SLOT_HAIR, PAWN_SLOT_HEADGEAR, PAWN_SLOT_VISOR, PAWN_SLOT_FACEPLATE};
    for (size_t i = 0; i < (sizeof(addonSlots) / sizeof(addonSlots[0])) && i < addonPaths.size(); ++i) {
        // only addons this class has no component for belong in the composite
        if (slotComponent(pawn, addonSlots[i])) {
            continue;
        }
        if (addonPaths[i].empty()) {
            continue;
        }
        USkeletalMesh* mesh = findSkeletalMeshByPath(addonPaths[i]);
        if (mesh) {
            addons.push_back(mesh);
        }
    }
    return applyCompositeAddons(pawn, addons);
}

bool NPCManager::isAddonSlot(int slot) {
    return slot == PAWN_SLOT_HAIR || slot == PAWN_SLOT_HEADGEAR || slot == PAWN_SLOT_VISOR || slot == PAWN_SLOT_FACEPLATE;
}

int NPCManager::addonPickerForSlot(int slot) const {
    switch (slot) {
        case PAWN_SLOT_HAIR:
            return NPC_PICK_LIVE_HAIR;
        case PAWN_SLOT_HEADGEAR:
            return NPC_PICK_LIVE_HEADGEAR;
        case PAWN_SLOT_VISOR:
            return NPC_PICK_LIVE_VISOR;
        case PAWN_SLOT_FACEPLATE:
            return NPC_PICK_LIVE_FACEPLATE;
        default:
            return -1;
    }
}

void NPCManager::applyMorphHeadToPawn(const std::string& pawnName, const std::string& morphName) {
    const std::vector<std::string> addonPaths = currentAddonPicks();

    // not resident yet? load its package first, then apply
    if (!morphName.empty() && !findMorphHeadByPath(morphName)) {
        ensureMorphResident(morphName, [this, pawnName, morphName, addonPaths]() {
            applyMorphHeadToPawn(pawnName, morphName);
        });
        return;
    }

    Application::instance().engine().postGameThreadTask([this, pawnName, morphName, addonPaths]() {
        ABioPawn* pawn = resolvePawn(pawnName);
        if (!pawn) {
            return;
        }
        UBioMorphFace* morph = morphName.empty() ? nullptr : findMorphHeadByPath(morphName);
        if (!morph && !morphName.empty()) {
            Logger->debug("NPC live edit: morph head no longer exists: " + morphName);
            return;
        }
        if (morph) {
            USkeletalMeshComponent* headComp = slotComponent(pawn, PAWN_SLOT_HEAD);
            if (!headComp) {
                Logger->debug("NPC live edit: pawn has no head component, cannot apply a morph head");
                char noHeadBuf[512];
                snprintf(noHeadBuf, sizeof(noHeadBuf), t("ui.npcs_table.failed_no_head"), pawnName.c_str());
                Application::instance().ui().toastManager.addToastNotification(noHeadBuf, ToastTypeError, 3.0);
                return;
            }
            // the face data is authored against the morph's own base head, so a
            // head left over from a different face renders nothing. re-base onto
            // m_oBaseHead, then rebuild the addon composite on top of it.
            if (morph->m_oBaseHead && headComp->SkeletalMesh != morph->m_oBaseHead) {
                Logger->debug("applyMorphHeadToPawn: re-basing head from " +
                              (headComp->SkeletalMesh ? FStringToUtf8(headComp->SkeletalMesh->GetFullPath()) : "(none)") + " onto " +
                              FStringToUtf8(morph->m_oBaseHead->GetFullPath()));
                applySlot(pawn, PAWN_SLOT_HEAD, morph->m_oBaseHead);
            }
        }
        applyMorphHead(pawn, morph);
        // put the hair and gear back on top of the freshly based head
        rebuildHeadComposite(pawn, addonPaths);
    });
}

#ifndef SDK_TARGET_LE3
void NPCManager::applyLifeCrustToPawn(const std::string& pawnName, const std::string& templateName, float lifeTime) {
    withPawn(pawnName, [this, templateName, lifeTime](ABioPawn* pawn) {
        applyLifeCrust(pawn, templateName, lifeTime);
    });
}

#endif

void NPCManager::deleteNPCPawn(ABioPawn* pawn) {
    if (!pawn || !isLiveObject(pawn)) {
        return;
    }
    const std::string pawnName = FStringToUtf8(pawn->GetName());
    // destroy the instance, SpawnPawn can reuse a name that is already in the level
    pawn->bNoDelete = 0;
    pawn->Destroy();
#ifdef SDK_TARGET_LE1
    headGearWanted.erase(pawn);
#endif
    if (trackedPawn == pawn) {
        trackedPawn = nullptr;
    }
    spawnedPawns.erase(std::remove(spawnedPawns.begin(), spawnedPawns.end(), pawn), spawnedPawns.end());
    Application::instance().engine().removeSpawnedActor(pawn);
    Application::instance().engine().removeSpawnedName(pawnName);
    Logger->debug("deleteNPC: '" + pawnName + "' destroyed (by pointer)");
}

void NPCManager::deleteNPC(const std::string& pawnName) {
    // removeActor resolves and validates by itself, so this does not need the pawn
    Application::instance().engine().postGameThreadTask([this, pawnName]() {
        if (AActor* actor = Application::instance().engine().findActorByName(pawnName)) {
            if (actor->IsA(ABioPawn::StaticClass())) {
                // drop the morph side table first, it would keep a dangling pointer
                forgetMorphHead(static_cast<ABioPawn*>(actor));
            }
        }
        Application::instance().engine().removeActor(pawnName);
        Application::instance().engine().removeSpawnedName(pawnName);
        Logger->debug("deleteNPC: '" + pawnName + "' removed from the spawned list");
    });
}

