std::string NPCManager::dumpPawn(ABioPawn* pawn) {
    std::ostringstream ss;
    if (!pawn) {
        ss << "NPC dump: no pawn selected\n";
        Logger->debug(ss.str());
        return ss.str();
    }

    const std::string pawnName = FStringToUtf8(pawn->GetName());

    ss << "================ NPC DUMP ================\n";
    ss << "name:     " << pawnName << "\n";
    ss << "fullName: " << FStringToUtf8(pawn->GetFullName()) << "\n";
    ss << "class:    " << (pawn->Class ? FStringToUtf8(pawn->Class->GetFullName()) : "(none)") << "\n";
    ss << "outer:    " << (pawn->Outer ? FStringToUtf8(pawn->Outer->GetFullName()) : "(none)") << "\n";
    ss << "live:     " << (isLiveObject(pawn) ? 1 : 0) << "\n";
    ss << "------------------------------------------\n";

    ss << "[components]\n";
    TArray<UActorComponent*>* components = (pawn->AllComponents.Count() > 0) ? &pawn->AllComponents : &pawn->Components;
    for (int i = 0; i < (int)components->Count(); ++i) {
        UActorComponent* comp = components->GetData()[i];
        if (!comp) {
            continue;
        }
        ss << "  [" << i << "] " << FStringToUtf8(comp->GetFullPath()) << "\n";
    }
    ss << "------------------------------------------\n";

    ss << "[slot availability]\n";
    for (int slot = 0; slot < PAWN_SLOT_COUNT; ++slot) {
        USkeletalMeshComponent* slotComp = slotComponent(pawn, slot);
        ss << "  " << t(slotLabelKey(slot)) << ": " << (slotComp ? "present" : "MISSING on this class");
        if (!slotComp && slot == PAWN_SLOT_HAIR) {
#ifdef SDK_TARGET_LE1
            ss << " (LE1 keeps hair in its own component, nothing to merge)";
#else
            ss << " (hair is merged into the head with MergeMeshes)";
#endif
        }
        ss << "\n";
    }

    for (int slot = 0; slot < PAWN_SLOT_COUNT; ++slot) {
        dumpComponent(ss, slotLabelKey(slot), slotComponent(pawn, slot));
    }
    dumpMorphHead(ss, morphHeadFor(pawn));
#ifndef SDK_TARGET_LE3
    dumpLifeCrust(ss, pawn);
#endif

    ss << "  [pawn]\n";
    describeObject(ss, "controller", pawn->Controller);
#ifdef SDK_TARGET_LE2
    describeObject(ss, "lightEnvironment", pawn->LightEnvironment);
#endif
#ifdef SDK_TARGET_LE2
    describeObject(ss, "loadout", pawn->Loadout);
    ss << "    meshTranslationOffset: " << pawn->MeshTranslationOffset.X << ", " << pawn->MeshTranslationOffset.Y << ", " << pawn->MeshTranslationOffset.Z
       << "\n";
#endif
    ss << "    walkSpeed: " << pawn->WalkSpeed << "\n";
#ifdef SDK_TARGET_LE2
    ss << "    turnSpeed: " << pawn->TurnSpeed << "\n";
#endif
    ss << "    accessories: " << pawn->m_aoAccessories.Count() << "\n";
#ifndef SDK_TARGET_LE3
    describeObject(ss, "animSetMgr", pawn->m_pAnimSetMgr);
#endif
#ifdef SDK_TARGET_LE2
    // these exist on LE2's BioPawn only
    describeObject(ss, "aiController", pawn->AIController);
    describeObject(ss, "factionClass", pawn->FactionClass);
    ss << "    bodyMaterialInstances: " << pawn->BodyMaterialInstances.Count() << "\n";
    ss << "    headMaterialInstances: " << pawn->HeadMaterialInstances.Count() << "\n";
#endif
    ss << "==========================================\n";

    const std::string text = ss.str();

    std::istringstream lines(text);
    std::string line;
    while (std::getline(lines, line)) {
        Logger->debug("npcDump[" + pawnName + "]: " + line);
    }

    SYSTEMTIME st;
    GetLocalTime(&st);
    char fileName[512] = {};
    snprintf(fileName, sizeof(fileName), "npc_dump_%s_%04d%02d%02d_%02d%02d%02d.txt", pawnName.c_str(), st.wYear, st.wMonth, st.wDay, st.wHour, st.wMinute,
             st.wSecond);
    std::ofstream dumpFile(fileName, std::ios::binary | std::ios::trunc);
    if (dumpFile.is_open()) {
        dumpFile << text;
        dumpFile.close();
    } else {
        Logger->debug("dumpPawn: could not write " + std::string(fileName));
    }

    char dumpBuf[512];
    snprintf(dumpBuf, sizeof(dumpBuf), t("ui.npcs_table.dumped"), pawnName.c_str(), fileName);
    Application::instance().ui().toastManager.addToastNotification(dumpBuf, ToastTypeSuccess, 3.0);

    return text;
}

