// bone count the slot currently carries, so the picker can flag assets that do not
// belong there. 0 when nothing is set yet, which disables the check.
int NPCManager::referenceBonesForPicker(int picker) const {
    ABioPawn* pawn = currentPawn();
    if (!pawn) {
        return 0;
    }
    int slot = -1;
    if (picker >= NPC_PICK_LIVE_BODY && picker <= NPC_PICK_LIVE_FACEPLATE) {
        slot = picker - NPC_PICK_LIVE_BODY;
    }
    if (slot < 0) {
        return 0;
    }
    USkeletalMeshComponent* comp = slotComponent(pawn, slot);
    return (comp && comp->SkeletalMesh) ? comp->SkeletalMesh->RefSkeleton.Count() : 0;
}

// resolving a pawn walks all of GObjObjects and builds a string per object, so it
// must not happen per picker per frame. cache it and only revalidate on a timer.
ABioPawn* NPCManager::currentPawn() const {
    const std::string name = Application::instance().ui().getSelectedPawnName();
    const double now = ImGui::GetTime();
    if (name != cachedPawnName || now - cachedPawnTime > 0.25) {
        cachedPawnName = name;
        cachedPawnTime = now;
        cachedPawn = nullptr;
        if (!name.empty()) {
            AActor* actor = Application::instance().engine().findActorByName(name);
            if (actor && actor->IsA(ABioPawn::StaticClass()) && isLiveObject(actor)) {
                cachedPawn = static_cast<ABioPawn*>(actor);
            }
        }
    }
    return cachedPawn;
}

void NPCManager::handlePendingSelect() {
    std::string newlySpawned;
    {
        std::lock_guard<std::mutex> lock(pendingSelectMtx);
        if (pendingSelect.empty()) {
            return;
        }
        newlySpawned = pendingSelect;
        pendingSelect.clear();
    }
    Application::instance().ui().collectPawns();
    AActor* spawned = Application::instance().engine().findActorByExactName(newlySpawned);
    if (!spawned) {
        spawned = Application::instance().engine().findActorByName(newlySpawned);
    }
    if (spawned) {
        Application::instance().ui().selectActor(spawned);
    }
}

// object paths are long and repetitive (BioG_..._PROCustom.HMF_HED_PROCustom_MDL), so
// the row shows the leaf name and the full path lives in the tooltip
static std::string leafName(const std::string& path) {
    const size_t lastDot = path.rfind('.');
    if (lastDot == std::string::npos) {
        return path;
    }
    return path.substr(lastDot + 1);
}

void NPCManager::renderPickerFilter(const char* id, const char* hint, char* filter) {
    ImGui::PushItemWidth(-100);
    ImGui::Text(ICON_FA_MAGNIFYING_GLASS);
    ImGui::SameLine();
    ImGui::InputTextWithHint(id, hint, filter, FILTER_SIZE);
    ImGui::PopItemWidth();
}

void NPCManager::renderAssetPicker(int picker, int slot, const std::vector<std::string>& items, const std::vector<std::string>& itemsLower,
                                   const std::function<void(const std::string&)>& onPicked, const std::string& filter) {
    if (picker < 0 || picker >= NPC_PICKER_COUNT) {
        return;
    }
    std::string& selected = picks[picker];

    const bool hasSlotSemantics = slot >= 0 && slot < PAWN_SLOT_COUNT;
    const int referenceBones = referenceBonesForPicker(picker);
    const bool hideUnknown = hasSlotSemantics && !showAllAssets;

    // the filter stays outside: an InputText inside a combo popup takes focus back
    // each frame, swallows the clicks and stops it closing
    const std::string filterLower = toLowerStr(filter);

    const std::string comboId = "##npc_combo_" + std::to_string(picker);
    const std::string preview = selected.empty() ? t("ui.animation_table.none") : leafName(selected);
    if (ImGui::BeginCombo(comboId.c_str(), preview.c_str())) {
        if (ImGui::Selectable(t("ui.animation_table.none"), selected.empty())) {
            selected.clear();
            onPicked("");
            ImGui::CloseCurrentPopup();
        }

        int shown = 0;
        for (size_t i = 0; i < items.size(); ++i) {
            if (i >= itemsLower.size()) {
                continue;
            }
            if (!filterLower.empty() && itemsLower[i].find(filterLower) == std::string::npos) {
                continue;
            }
            const bool known = !hasSlotSemantics || isKnownGoodForSlot(slot, itemsLower[i]);
            if (hideUnknown && !known) {
                continue;
            }
            if (shown >= 100 && filterLower.empty()) {
                ImGui::TextDisabled(t("ui.npcs_table.list_capped"));
                break;
            }

            // the bone count makes the list self explanatory: heads sit around 40,
            // bodies around 110, weapons under 15
            std::string label = leafName(items[i]);
            bool flagged = false;
            if (hasSlotSemantics && i < skeletalMeshBones.size()) {
                const int bones = skeletalMeshBones[i];
                label += "  (" + std::to_string(bones) + "b)";
                if (referenceBones > 0 && bones > 0) {
                    const int worst = (std::max)(referenceBones, bones);
                    const int diff = worst - (std::min)(referenceBones, bones);
                    flagged = (diff * 100) / worst > 40;
                }
                if (!known) {
                    label += " " + std::string(ICON_FA_CIRCLE_QUESTION);
                }
            }
            if (flagged) {
                label += " " + std::string(ICON_FA_TRIANGLE_EXCLAMATION);
            }

            const std::string id = label + "##npc_opt_" + std::to_string(picker) + "_" + std::to_string(i);
            if (ImGui::Selectable(id.c_str(), items[i] == selected)) {
                selected = items[i];
                onPicked(items[i]);
                ImGui::CloseCurrentPopup();
            }
            ++shown;
        }

        if (shown == 0) {
            ImGui::TextDisabled(t("ui.vfx_table.no_matches"));
        }
        if (hideUnknown) {
            ImGui::Separator();
            ImGui::TextDisabled(t("ui.npcs_table.known_good_only"));
        }
        ImGui::EndCombo();
    }
}

void NPCManager::renderPickerTable(const std::vector<PawnSlotRow>& rows, const char* filterId, const char* filterHint, char* filter,
                                   const std::function<void(const PawnSlotRow&, const std::string&)>& row) {
    renderPickerFilter(filterId, filterHint, filter);
    if (rows.empty()) {
        return;
    }

    const std::string tableId = std::string(filterId) + "_tbl";
    ImGui::BeginTable(tableId.c_str(), 2, ImGuiTableFlags_SizingFixedFit | ImGuiTableFlags_SizingStretchProp);
    for (const PawnSlotRow& entry : rows) {
        ImGui::TableNextRow();
        ImGui::TableSetColumnIndex(0);
        ImGui::AlignTextToFramePadding();
        ImGui::TextUnformatted(t(entry.labelKey));
        ImGui::TableSetColumnIndex(1);
        row(entry, filter);
    }
    ImGui::EndTable();
}

const std::vector<PawnSlotRow>& NPCManager::meshPickerRows(int pickerBase) const {
    static std::vector<PawnSlotRow> spawnRows;
    static std::vector<PawnSlotRow> liveRows;
    if (spawnRows.empty()) {
        for (int i = 0; i < slotRowCount; ++i) {
            spawnRows.push_back({slotRows[i].picker - (NPC_PICK_LIVE_BODY - NPC_PICK_SPAWN_BODY), slotRows[i].slot, slotRows[i].labelKey});
        }
        liveRows.assign(slotRows, slotRows + slotRowCount);
    }
    return pickerBase == NPC_PICK_SPAWN_BODY ? spawnRows : liveRows;
}

const std::vector<PawnSlotRow>& NPCManager::facePickerRows(int morphPicker, int crustPicker) const {
    static std::vector<PawnSlotRow> spawnFace;
    static std::vector<PawnSlotRow> liveFace;
    static bool built = false;
    if (!built) {
        built = true;
        spawnFace = {
            {morphPicker, -1, "ui.npcs_table.morph_head"}
        };
        liveFace = spawnFace;
#ifndef SDK_TARGET_LE3
        if (crustPicker >= 0) {
            spawnFace.push_back({crustPicker, -1, "ui.npcs_table.life_crust"});
            liveFace.push_back({crustPicker, -1, "ui.npcs_table.life_crust"});
        }
#endif
    }
    return morphPicker == NPC_PICK_SPAWN_MORPH ? spawnFace : liveFace;
}

void NPCManager::renderMorphFacePanel(ABioPawn* pawn, const std::string& pawnName) {
    UBioMorphFace* morph = morphHeadFor(pawn);
    if (!morph) {
        return;
    }

    if (!ImGui::CollapsingHeader((std::string(ICON_FA_MASK_FACE " ") + t("ui.npcs_table.morph_face")).c_str())) {
        return;
    }
    ImGui::Indent();

    const int colorCount = morph->m_oMaterialOverrides ? (int)morph->m_oMaterialOverrides->m_aColorOverrides.Count() : 0;

    // seed before anything indexes: an empty vector would be written past its end
    static std::string morphColorSeedKey;
    const std::string morphKey = FStringToUtf8(morph->GetFullPath()) + "#" + std::to_string(colorCount);
    if (morphKey != morphColorSeedKey) {
        morphColorSeedKey = morphKey;
        morphColorValues.clear();
        morphColorValues.reserve((size_t)colorCount * 4);
        for (int i = 0; i < colorCount; ++i) {
            const FLinearColor& c = morph->m_oMaterialOverrides->m_aColorOverrides.GetData()[i].cValue;
            morphColorValues.push_back(c.R);
            morphColorValues.push_back(c.G);
            morphColorValues.push_back(c.B);
            morphColorValues.push_back(c.A);
        }
    }

    ImGui::TextDisabled(t("ui.npcs_table.morph_face"), FStringToUtf8(morph->GetFullPath()).c_str());
    ImGui::TextDisabled(t("ui.npcs_table.morph_shared_warning"));

    if (colorCount > 0) {
        for (int i = 0; i < colorCount; ++i) {
            const size_t base = (size_t)i * 4;
            if (base + 4 > morphColorValues.size()) {
                break;
            }
            const FColorParameter& parameter = morph->m_oMaterialOverrides->m_aColorOverrides.GetData()[i];
            const char* parameterName = parameter.nName.GetName();
            const std::string label = (parameterName ? parameterName : ("color_" + std::to_string(i))) + "##npc_morph_color_" + std::to_string(i);
            float* rgba = &morphColorValues[base];
            if (ImGui::ColorEdit4(label.c_str(), rgba, ImGuiColorEditFlags_NoInputs)) {
                applyMorphColor(pawnName, i, FLinearColor(rgba[0], rgba[1], rgba[2], rgba[3]));
            }
        }
        ImGui::Separator();
    }

    // no parameter editor: the face is vertex buffers and the character
    // creator's parameter data is not resident in gameplay
    ImGui::TextDisabled(t("ui.npcs_table.morph_params_unavailable"));

    if (ImGui::Button((std::string(ICON_FA_ARROW_ROTATE_RIGHT " ") + t("ui.npcs_table.reapply_morph")).c_str())) {
        reapplyMorphHead(pawnName);
    }

    ImGui::Unindent();
}

// a manual material assignment has to be re-pushed after the pawn rebuilds its own
// instances, otherwise the next mesh change silently undoes it
void NPCManager::reapplyMaterialOverrides(ABioPawn* pawn) {
    if (!pawn) {
        return;
    }
    const std::string pawnName = FStringToUtf8(pawn->GetName());
    int applied = 0;
    std::map<std::string, std::string> overrides;
    {
        std::lock_guard<std::mutex> lock(stateMtx);
        overrides = materialOverrides;
    }
    for (int slot = 0; slot < PAWN_SLOT_COUNT; ++slot) {
        USkeletalMeshComponent* comp = slotComponent(pawn, slot);
        if (!comp) {
            continue;
        }
        const std::string slotTag = std::to_string(slot);
        for (const auto& entry : overrides) {
            const std::string prefix = pawnName + "|" + slotTag + "|";
            if (entry.first.rfind(prefix, 0) != 0) {
                continue;
            }
            UMaterialInterface* material = findMaterialByPath(entry.second);
            if (material) {
                comp->SetMaterial(atoi(entry.first.c_str() + prefix.size()), material);
                ++applied;
            }
        }
    }
    if (applied > 0) {
        Logger->debug("reapplyMaterialOverrides: re-pushed " + std::to_string(applied) + " manual material assignments on '" + pawnName + "'");
    }
}

void NPCManager::setMaterialOnPawn(const std::string& pawnName, int slot, int elementIndex, const std::string& materialPath) {
    {
        std::lock_guard<std::mutex> lock(stateMtx);
        const std::string key = pawnName + "|" + std::to_string(slot) + "|" + std::to_string(elementIndex);
        if (materialPath.empty()) {
            materialOverrides.erase(key);
        } else {
            materialOverrides[key] = materialPath;
        }
    }
    withPawn(pawnName, [this, pawnName, slot, elementIndex, materialPath](ABioPawn* pawn) {
        USkeletalMeshComponent* comp = slotComponent(pawn, slot);
        if (!comp) {
            return;
        }
        if (materialPath.empty()) {
            UMaterialInterface* base = comp->GetBaseMaterial(elementIndex);
            comp->SetMaterial(elementIndex, base);
            Logger->debug("resetMaterialOnPawn: '" + pawnName + "' slot " + std::to_string(slot) + " element " + std::to_string(elementIndex) + " -> " +
                          (base ? FStringToUtf8(base->GetFullPath()) : "(none)"));
            return;
        }
        UMaterialInterface* material = findMaterialByPath(materialPath);
        if (!material) {
            Logger->debug("setMaterialOnPawn: material no longer exists: " + materialPath);
            return;
        }
        comp->SetMaterial(elementIndex, material);
        Logger->debug("setMaterialOnPawn: '" + pawnName + "' slot " + std::to_string(slot) + " element " + std::to_string(elementIndex) + " -> " +
                      materialPath + " readback=" + FStringToUtf8(comp->GetMaterial(elementIndex)->GetFullPath()));
    });
}

void NPCManager::resetMaterialOnPawn(const std::string& pawnName, int slot, int elementIndex) {
    setMaterialOnPawn(pawnName, slot, elementIndex, "");
}

void NPCManager::recreateMaterialInstance(const std::string& pawnName, int slot, int elementIndex) {
    withPawn(pawnName, [this, pawnName, slot, elementIndex](ABioPawn* pawn) {
        USkeletalMeshComponent* comp = slotComponent(pawn, slot);
        if (!comp) {
            return;
        }
        UMaterialInstanceConstant* mic = comp->CreateAndSetMaterialInstanceConstant(elementIndex);
        Logger->debug("recreateMaterialInstance: '" + pawnName + "' slot " + std::to_string(slot) + " element " + std::to_string(elementIndex) + " -> " +
                      (mic ? FStringToUtf8(mic->GetFullPath()) : "(null)"));
    });
}

void NPCManager::renderMaterialsPanel(ABioPawn* pawn) {
    if (!pawn) {
        return;
    }
    if (!ImGui::CollapsingHeader((std::string(ICON_FA_PALETTE " ") + t("ui.npcs_table.materials")).c_str())) {
        return;
    }
    ImGui::Indent();

    renderPickerFilter("##npc_material_filter", t("ui.npcs_table.filter_assets"), materialPickerFilter);
    const std::string filterLower = toLowerStr(materialPickerFilter);

    const std::string pawnName = FStringToUtf8(pawn->GetName());
    bool any = false;
    for (int slot = 0; slot < PAWN_SLOT_COUNT; ++slot) {
        USkeletalMeshComponent* comp = slotComponent(pawn, slot);
        if (!comp || comp->Materials.Count() == 0) {
            continue;
        }
        any = true;

        ImGui::Separator();
        ImGui::TextUnformatted(t(slotLabelKey(slot)));
        // index | name | combo, so a long asset name can never push the combo out
        // of the window and leave its dropdown opening off screen
        ImGui::BeginTable(("##npc_materials_" + std::to_string(slot)).c_str(), 3, ImGuiTableFlags_SizingFixedFit | ImGuiTableFlags_SizingStretchProp);
        for (int i = 0; i < (int)comp->Materials.Count(); ++i) {
            UMaterialInterface* current = comp->GetMaterial(i);
            ImGui::PushID(("mat_" + std::to_string(slot) + "_" + std::to_string(i)).c_str());

            ImGui::TableNextRow();
            ImGui::TableSetColumnIndex(0);
            ImGui::AlignTextToFramePadding();
            ImGui::TextDisabled("[%d]", i);

            ImGui::TableSetColumnIndex(1);
            ImGui::AlignTextToFramePadding();
            // the leaf name, not the full package path: a path is 40+ characters and
            // would overflow the column
            ImGui::TextUnformatted(current ? leafName(FStringToUtf8(current->GetFullPath())).c_str() : t("ui.animation_table.none"));

            ImGui::TableSetColumnIndex(2);
            ImGui::PushItemWidth(90.0f);
            if (ImGui::BeginCombo("##mat_combo", ICON_FA_PALETTE "##")) {
                if (ImGui::Selectable(t("ui.npcs_table.mesh_default"), false)) {
                    resetMaterialOnPawn(pawnName, slot, i);
                    ImGui::CloseCurrentPopup();
                }
                int shown = 0;
                for (size_t m = 0; m < materialAssets.size() && m < materialAssetsLower.size(); ++m) {
                    if (!filterLower.empty() && materialAssetsLower[m].find(filterLower) == std::string::npos) {
                        continue;
                    }
                    if (shown >= 100 && filterLower.empty()) {
                        ImGui::TextDisabled(t("ui.npcs_table.list_capped"));
                        break;
                    }
                    const std::string id = leafName(materialAssets[m]) + "##mat_opt_" + std::to_string(m);
                    if (ImGui::Selectable(id.c_str(), false)) {
                        setMaterialOnPawn(pawnName, slot, i, materialAssets[m]);
                        ImGui::CloseCurrentPopup();
                    }
                    ++shown;
                }
                if (shown == 0) {
                    ImGui::TextDisabled(t("ui.vfx_table.no_matches"));
                }
                ImGui::EndCombo();
            }
            ImGui::SameLine();
            if (ImGui::SmallButton(ICON_FA_ROTATE "##mic")) {
                recreateMaterialInstance(pawnName, slot, i);
            }
            ImGui::SameLine();
            if (ImGui::SmallButton(ICON_FA_ROTATE_LEFT "##reset")) {
                resetMaterialOnPawn(pawnName, slot, i);
            }
            ImGui::PopItemWidth();
            ImGui::PopID();
        }
        ImGui::EndTable();
    }

    if (!any) {
        ImGui::TextDisabled(t("ui.npcs_table.no_materials"));
    }
    ImGui::Unindent();
}

// one row per appearance slot, shared by both panels: the spawn picker ids are the
// live ones minus the live block
const PawnSlotRow NPCManager::slotRows[] = {
    {NPC_PICK_LIVE_BODY,      PAWN_SLOT_BODY,      "ui.npcs_table.body_mesh"     },
    {NPC_PICK_LIVE_HEAD,      PAWN_SLOT_HEAD,      "ui.npcs_table.head_mesh"     },
    {NPC_PICK_LIVE_HAIR,      PAWN_SLOT_HAIR,      "ui.npcs_table.hair_mesh"     },
    {NPC_PICK_LIVE_HEADGEAR,  PAWN_SLOT_HEADGEAR,  "ui.npcs_table.headgear_mesh" },
    {NPC_PICK_LIVE_VISOR,     PAWN_SLOT_VISOR,     "ui.npcs_table.visor_mesh"    },
    {NPC_PICK_LIVE_FACEPLATE, PAWN_SLOT_FACEPLATE, "ui.npcs_table.faceplate_mesh"},
};
const int NPCManager::slotRowCount = (int)(sizeof(slotRows) / sizeof(slotRows[0]));

// a pawn class is a shell, its meshes, anim tree, anim sets and morph face are all
// null. the level's own instances carry the appearance, so one goes to Spawn as the
// template and fills in whatever the engine did not copy.
ABioPawn* NPCManager::findAppearanceTemplate(UClass* cls) {
    if (!cls) {
        return nullptr;
    }

    //
    // never one of ours: on the second spawn the pawn we just made would be picked,
    // and Spawn wants a CDO or archetype, not a ticked actor
    const std::vector<std::string> ours = Application::instance().engine().spawnedNames();
    int sameClass = 0;
    int withMesh = 0;
    int skipped = 0;
    ABioPawn* best = nullptr;
    ABioPawn* fallback = nullptr;

    forEachOf<ABioPawn>([&](ABioPawn* obj) {
        if (!obj || !isLiveObject(obj) || !obj->Class) {
            return;
        }
        if (!isUsableSpawnTemplate(obj)) {
            ++skipped;
            return;
        }
        if (obj->Class != cls && !isSubclassOf(obj->Class, cls)) {
            return;
        }
        ++sameClass;
        const std::string objName = FStringToUtf8(obj->GetName());
        if (objName.rfind("Default__", 0) == 0) {
            return; // a class default object carries no meshes either
        }
        if (std::find(ours.begin(), ours.end(), objName) != ours.end()) {
            ++skipped;
            return; // one of ours, not a usable archetype
        }
        if (!fallback) {
            fallback = obj;
        }
        if (!best && obj->Mesh && obj->Mesh->SkeletalMesh) {
            ++withMesh;
            best = obj;
        }
    });

    ABioPawn* result = best ? best : fallback;
    std::ostringstream ss;
    ss << "findAppearanceTemplate: '" << FStringToUtf8(cls->GetFullName()) << "' found " << sameClass << " object(s), " << withMesh
       << " with a body mesh, skipped " << skipped << " we spawned ourselves, using " << (result ? FStringToUtf8(result->GetFullPath()) : std::string("NONE"));
    Logger->debug(ss.str());
    return result;
}

// fill in what the engine did not copy from the template: the character only needs
// a mesh when the class has none, but the anim tree and anim sets have to come too
// or it renders but never animates. explicit picks always win.
void NPCManager::copyAppearanceFrom(ABioPawn* pawn, ABioPawn* source) {
    if (!pawn || !source) {
        return;
    }
    int filled = 0;

    for (int slot = 0; slot < PAWN_SLOT_COUNT; ++slot) {
        USkeletalMeshComponent* mine = slotComponent(pawn, slot);
        USkeletalMeshComponent* theirs = slotComponent(source, slot);
        if (!mine || !theirs || !theirs->SkeletalMesh || (mine->SkeletalMesh && mine->SkeletalMesh != theirs->SkeletalMesh)) {
            continue;
        }
        applySlot(pawn, slot, theirs->SkeletalMesh);
        ++filled;
    }

    USkeletalMeshComponent* body = slotComponent(pawn, PAWN_SLOT_BODY);
    USkeletalMeshComponent* sourceBody = slotComponent(source, PAWN_SLOT_BODY);
    if (body && sourceBody) {
        if (!body->PhysicsAsset && sourceBody->PhysicsAsset) {
            body->PhysicsAsset = sourceBody->PhysicsAsset;
        }
        if (!body->Animations && sourceBody->Animations) {
            body->Animations = sourceBody->Animations;
            ++filled;
            Logger->debug("copyAppearanceFrom: shared the template anim tree, both pawns will animate identically");
        }
        if (body->AnimSets.Count() == 0 && sourceBody->AnimSets.Count() > 0) {
            body->AnimSets = sourceBody->AnimSets;
            ++filled;
        }
    }

    if (!morphHeadFor(pawn) && morphHeadFor(source)) {
        applyMorphHead(pawn, morphHeadFor(source));
        ++filled;
    }

    if (filled > 0) {
        rebuildPawnMaterials(pawn);
        reapplyHeadMesh(pawn);
        std::ostringstream ss;
        ss << "copyAppearanceFrom: '" << FStringToUtf8(pawn->GetName()) << "' filled " << filled << " missing pieces from '" << FStringToUtf8(source->GetName())
           << "'";
        Logger->debug(ss.str());
    }
}

// a morph face only exists once its package is loaded, which is why picking
// BIOG_MORPH_FACE.Player_Base_Female reported it missing. instantiating one by hand
// is not possible, no StaticConstructObject resolver, so load the package instead.
void NPCManager::ensureMorphResident(const std::string& morphPath, const std::function<void()>& onLoaded) {
    if (morphPath.empty() || findMorphHeadByPath(morphPath)) {
        if (onLoaded) {
            onLoaded();
        }
        return;
    }

    const size_t dot = morphPath.find('.');
    if (dot == std::string::npos) {
        if (onLoaded) {
            onLoaded();
        }
        return;
    }
    const std::string packageName = morphPath.substr(0, dot);
    const std::string packagePath = findPackagePath(packageName);
    if (packagePath.empty()) {
        Logger->debug("ensureMorphResident: no .pcc found for package '" + packageName + "'");
        if (onLoaded) {
            onLoaded();
        }
        return;
    }

    char loadingBuf[512];
    snprintf(loadingBuf, sizeof(loadingBuf), t("ui.npcs_table.morph_loading"), packageName.c_str());
    Application::instance().ui().toastManager.addToastNotification(loadingBuf, ToastTypeInfo, 3.0);
    Logger->debug("ensureMorphResident: loading '" + packagePath + "' for morph '" + morphPath + "'");

    Application::instance().engine().postPackageLoad(packagePath, [this, morphPath, onLoaded]() {
        applyAssets();
        if (findMorphHeadByPath(morphPath)) {
            Logger->debug("ensureMorphResident: '" + morphPath + "' is now resident");
        } else {
            Logger->debug("ensureMorphResident: '" + morphPath + "' still not found after loading");
        }
        if (onLoaded) {
            onLoaded();
        }
    });
}

std::string NPCManager::inferDisplayName(const std::string& classFullName) {
    std::string name = classFullName;
    const size_t lastDot = name.rfind('.');
    if (lastDot != std::string::npos) {
        name = name.substr(lastDot + 1);
    }
    static const char* const prefixes[] = {"SFXPawn_", "BioPawn_", "BioPawn", "SFXPawn", "Pawn_", "Pawn"};
    for (const char* prefix : prefixes) {
        const size_t len = strlen(prefix);
        if (name.rfind(prefix, 0) == 0) {
            name = name.substr(len);
            break;
        }
    }

    std::string out;
    for (size_t i = 0; i < name.size(); ++i) {
        const char c = name[i];
        if (c == '_' || c == '-') {
            out += ' ';
            continue;
        }
        if (i > 0 && isupper((unsigned char)c) && !isupper((unsigned char)name[i - 1]) && name[i - 1] != ' ') {
            out += ' ';
        }
        out += c;
    }
    if (!out.empty()) {
        out[0] = (char)toupper((unsigned char)out[0]);
    }
    return out.empty() ? classFullName : out;
}

void NPCManager::rebuildResidentPawns() {
    loadedPawnPresets.clear();
    loadedPawnPresets.reserve(pawnClasses.size());
    for (const std::string& cls : pawnClasses) {
        ScannedPawn preset;
        preset.classFullName = cls;
        preset.displayName = inferDisplayName(cls);
        loadedPawnPresets.push_back(preset);
    }
}

// resident classes are already collected per asset refresh, so keep their short
// export names here: an index row then costs a compare instead of a full walk
bool NPCManager::isPawnExportResident(const std::string& exportName) const {
    const std::string wanted = toLowerStr(exportName);
    for (const std::string& resident : residentPawnShortNamesLower) {
        if (resident == wanted) {
            return true;
        }
    }
    return false;
}

// the pcc list is a disk walk over the whole install, so cache it: the files do not
// change while the game is running
std::string NPCManager::findPackagePath(const std::string& sourcePackage) {
    {
        std::lock_guard<std::mutex> lock(packageCacheMtx);
        if (packageCacheValid) {
            auto it = packageCache.find(toLowerStr(sourcePackage));
            return it == packageCache.end() ? std::string() : it->second;
        }
    }

    std::map<std::string, std::string> built;
    for (const PccFile& pcc : collectGamePccFiles()) {
        built.emplace(toLowerStr(std::filesystem::path(pcc.path).stem().string()), pcc.path);
    }

    std::lock_guard<std::mutex> lock(packageCacheMtx);
    packageCache = std::move(built);
    packageCacheValid = true;
    Logger->debug("findPackagePath: cached " + std::to_string(packageCache.size()) + " packages");
    auto it = packageCache.find(toLowerStr(sourcePackage));
    return it == packageCache.end() ? std::string() : it->second;
}

void NPCManager::withPawn(const std::string& pawnName, const std::function<void(ABioPawn*)>& fn) {
    Application::instance().engine().postGameThreadTask([this, pawnName, fn]() {
        ABioPawn* pawn = resolvePawn(pawnName);
        if (pawn) {
            fn(pawn);
        }
    });
}

std::vector<std::string> NPCManager::currentAddonPicks() const {
    static const int addonSlots[] = {PAWN_SLOT_HAIR, PAWN_SLOT_HEADGEAR, PAWN_SLOT_VISOR, PAWN_SLOT_FACEPLATE};
    std::vector<std::string> paths;
    paths.reserve(sizeof(addonSlots) / sizeof(addonSlots[0]));
    for (int slot : addonSlots) {
        const int picker = addonPickerForSlot(slot);
        if (picker >= 0) {
            paths.push_back(picks[picker]);
        }
    }
    return paths;
}

// the pcc name and the runtime object path disagree (SFXGamePawns lives inside
// SFXGame.pcc), so try every plausible spelling before calling a class absent
UClass* NPCManager::resolvePawnClass(const std::string& packageName, const std::string& exportName) {
    const std::vector<std::string> candidates = {
        "Class " + packageName + "." + exportName,
        "Class " + exportName,
        "Class " + packageName + "." + packageName + "." + exportName,
    };
    for (const std::string& candidate : candidates) {
        std::wstring wide = toWString(candidate);
        UClass* cls = UObject::FindClass(wide.c_str());
        if (cls) {
            return cls;
        }
    }

    if (!UObject::GObjObjects || !UObject::GObjObjects->GetData()) {
        return nullptr;
    }
    UClass* found = nullptr;
    const std::string wanted = toLowerStr(exportName);
    const int count = (int)UObject::GObjObjects->Count();
    for (int i = 0; i < count && !found; ++i) {
        UObject* obj = UObject::GObjObjects->GetData()[i];
        if (!obj || !obj->Class || !obj->IsA(UClass::StaticClass())) {
            continue;
        }
        std::string full = FStringToUtf8(obj->GetFullName());
        const size_t lastDot = full.rfind('.');
        if (lastDot != std::string::npos) {
            full = full.substr(lastDot + 1);
        }
        if (toLowerStr(full) == wanted) {
            found = static_cast<UClass*>(obj);
        }
    }
    if (found) {
        Logger->debug("resolvePawnClass: '" + exportName + "' found by leaf name as " + FStringToUtf8(found->GetFullName()));
    }
    return found;
}

void NPCManager::spawnFromIndexRow(const PawnIndexRow& row) {
    const Transform spawnTransform = Application::instance().ui().getSpawnTransform();

    auto spawnClass = [this, spawnTransform](UClass* cls) {
        PawnSpawnConfig config;
        config.classFullName = FStringToUtf8(cls->GetFullName());
        Application::instance().engine().postGameThreadTask([this, config, spawnTransform]() {
            spawnNPC(config, spawnTransform);
        });
    };

    UClass* cls = resolvePawnClass(row.packageName, row.exportName);
    if (cls) {
        spawnClass(cls);
        return;
    }

    const std::string packagePath = findPackagePath(row.sourcePackage);
    if (packagePath.empty()) {
        Logger->debug("spawnFromIndexRow: no .pcc on disk for source '" + row.sourcePackage + "' (" + row.exportName + ")");
        char buf[512];
        snprintf(buf, sizeof(buf), t("ui.npcs_table.preset_package_missing"), row.sourcePackage.c_str());
        Application::instance().ui().toastManager.addToastNotification(buf, ToastTypeError, 4.0);
        return;
    }

    // cooked LEVEL packages, not asset packages: LoadPackage pulls in the whole
    // level synchronously on the game thread
    char loadingBuf[512];
    snprintf(loadingBuf, sizeof(loadingBuf), t("ui.npcs_table.preset_loading"), row.packageName.c_str());
    Application::instance().ui().toastManager.addToastNotification(loadingBuf, ToastTypeInfo, 4.0);
    const double startedAt = ImGui::GetTime();
    Logger->debug("spawnFromIndexRow: loading level package '" + packagePath + "' for '" + row.exportName + "'");

    Application::instance().engine().postPackageLoad(packagePath, [this, row, spawnClass, startedAt]() {
        std::ostringstream timing;
        timing << "spawnFromIndexRow: '" << row.packageName << "' took " << (ImGui::GetTime() - startedAt) << "s to load and spawn " << row.exportName;
        Logger->debug(timing.str());
        UClass* loaded = resolvePawnClass(row.packageName, row.exportName);
        if (!loaded) {
            char buf[512];
            snprintf(buf, sizeof(buf), t("ui.spawn_table.failed_class_not_found"), row.exportName.c_str());
            Application::instance().ui().toastManager.addToastNotification(buf, ToastTypeError, 4.0);
            return;
        }
        spawnClass(loaded);
    });
}

std::filesystem::path NPCManager::userIndexPath() {
    const char* appData = getenv("APPDATA");
    if (!appData || !*appData) {
        return {};
    }
    std::error_code ec;
    std::filesystem::path dir = std::filesystem::path(appData) / "SuperAdjustmentStudio";
    std::filesystem::create_directories(dir, ec);
    // per game, the classes each game ships differ completely
    static const char* const gameSuffix = []() -> const char* {
#ifdef SDK_TARGET_LE1
        return "le1";
#elif defined(SDK_TARGET_LE3)
        return "le3";
#else
        return "le2";
#endif
    }();
    return dir / (std::string("npcs_index_") + gameSuffix + ".json");
}

static bool looksLikePawnName(const std::string& name) {
    return name.rfind("SFXPawn", 0) == 0 || name.rfind("BioPawn", 0) == 0;
}

static bool isPawnClassExport(const PCCExport& e) {
    if (e.objectName.rfind("Default__", 0) == 0) {
        return false;
    }
    return looksLikePawnName(e.superName) || e.objectName == "BioPawn" || e.objectName == "SFXPawn";
}

static bool isModPackagePath(const std::string& relPath) {
    return relPath.find("DLC_MOD_") != std::string::npos && relPath.find("DLC_MOD_LE2PATCH") == std::string::npos;
}

void NPCManager::ensureIndexLoaded() {
    if (indexRowsLoaded) {
        return;
    }
    indexRowsLoaded = true;
    {
        std::lock_guard<std::mutex> lock(stateMtx);
        indexRows.clear();
#ifdef SDK_TARGET_LE1
        // characters are baked into the generated index, only the pawn rows can be
        // replaced by a user index
        characterRows.clear();
        for (int i = 0; i < staticCharacterIndexCount; ++i) {
            CharacterIndexRow row;
            row.displayName = staticCharacterIndex[i].displayName;
            row.groupName = staticCharacterIndex[i].groupName;
            row.sourcePackage = staticCharacterIndex[i].sourcePackage;
            characterRows.push_back(row);
        }
#endif
    }

    const std::filesystem::path userPath = userIndexPath();
    if (!userPath.empty() && std::filesystem::exists(userPath)) {
        std::ifstream file(userPath, std::ios::binary);
        if (file) {
            try {
                const nlohmann::json doc = nlohmann::json::parse(file);
                for (const auto& item : doc) {
                    PawnIndexRow row;
                    row.displayName = item.value("name", "");
                    row.exportName = item.value("export", "");
                    row.packageName = item.value("package", "");
                    row.sourcePackage = item.value("source", "");
                    row.category = item.value("category", "Background NPCs");
                    if (!row.exportName.empty()) {
                        std::lock_guard<std::mutex> lock(stateMtx);
                        indexRows.push_back(row);
                    }
                }
                Logger->debug("ensureIndexLoaded: using the user index at " + userPath.string() + " with " + std::to_string(indexRows.size()) + " entries");
            } catch (const std::exception& e) {
                Logger->error(std::string("ensureIndexLoaded: could not read the user index: ") + e.what());
            }
        }
    }

    {
        std::lock_guard<std::mutex> lock(stateMtx);
        if (indexRows.empty()) {
            for (int i = 0; i < staticPawnIndexCount; ++i) {
                const StaticPawnIndexEntry& e = staticPawnIndex[i];
                indexRows.push_back(PawnIndexRow{e.displayName, e.exportName, e.packageName, e.sourcePackage, e.category});
            }
        }
        Logger->debug("ensureIndexLoaded: using the built-in index with " + std::to_string(indexRows.size()) + " entries");
    }
    std::lock_guard<std::mutex> lock(stateMtx);
    ++indexVersion;
}

void NPCManager::generateUserIndex() {
    if (indexScanRunning.load()) {
        return;
    }
    indexScanCancel = false;
    indexScanRunning = true;
    indexScanDone = 0;
    indexScanFound = 0;

    const bool includeMods = indexIncludeMods;

    indexFuture = std::async(std::launch::async, [this, includeMods]() {
        const std::vector<PccFile> files = collectGamePccFiles();
        indexScanTotal.store((int)files.size());
        std::vector<PawnIndexRow> rows;
        int skipped = 0;
        int failed = 0;
        int done = 0;

        for (const PccFile& pcc : files) {
            if (indexScanCancel.load()) {
                break;
            }
            if (!includeMods && isModPackagePath(pcc.relPath)) {
                ++skipped;
                ++done;
                indexScanDone.store(done);
                continue;
            }

            PCCParser parser(pcc.path);
            if (!parser.parse()) {
                ++failed;
                ++done;
                indexScanDone.store(done);
                continue;
            }
            const PCCFile& data = parser.fileData();
            for (const PCCExport& e : data.exports) {
                if (!isPawnClassExport(e)) {
                    continue;
                }
                // a level pcc holds a second copy under TheWorld.PersistentLevel, only
                // the package group copy is the runtime class
                std::string prefix;
                const size_t dot = e.fullName.rfind('.');
                if (dot != std::string::npos) {
                    prefix = e.fullName.substr(0, dot);
                }
                if (prefix.rfind("TheWorld", 0) == 0 || prefix.find("PersistentLevel") != std::string::npos) {
                    continue;
                }
                const bool known = std::any_of(rows.begin(), rows.end(), [&](const PawnIndexRow& r) {
                    return toLowerStr(r.exportName) == toLowerStr(e.objectName);
                });
                if (known) {
                    continue;
                }
                PawnIndexRow row;
                row.exportName = e.objectName;
                row.packageName = prefix;
                if (prefix.empty()) {
                    row.packageName = std::filesystem::path(pcc.path).stem().string();
                }
                row.sourcePackage = std::filesystem::path(pcc.path).stem().string();
                row.displayName = NPCManager::inferDisplayName("Class " + row.exportName);
                row.category = "Background NPCs";
                rows.push_back(row);
            }
            ++done;
            indexScanDone.store(done);
        }

        indexScanFound.store((int)rows.size());

        for (PawnIndexRow& row : rows) {
            for (int i = 0; i < staticPawnIndexCount; ++i) {
                if (toLowerStr(staticPawnIndex[i].exportName) == toLowerStr(row.exportName)) {
                    row.displayName = staticPawnIndex[i].displayName;
                    row.category = staticPawnIndex[i].category;
                    break;
                }
            }
        }

        const std::filesystem::path out = userIndexPath();
        bool written = false;
        if (!out.empty()) {
            std::ofstream file(out, std::ios::binary | std::ios::trunc);
            if (file) {
                nlohmann::json doc = nlohmann::json::array();
                for (const PawnIndexRow& row : rows) {
                    doc.push_back({
                        {"name",     row.displayName  },
                        {"export",   row.exportName   },
                        {"package",  row.packageName  },
                        {"source",   row.sourcePackage},
                        {"category", row.category     }
                    });
                }
                file << doc.dump(1);
                written = true;
            }
        }

        {
            std::lock_guard<std::mutex> lock(stateMtx);
            indexRows = rows;
            ++indexVersion;
        }
        indexScanRunning = false;

        const char* modNote = includeMods ? "included" : "excluded";
        std::ostringstream ss;
        ss << "generateUserIndex: scanned " << done << "/" << indexScanTotal.load() << " packages, skipped " << skipped << ", failed " << failed << ", found "
           << rows.size() << " pawn classes, mods " << modNote << ", written to " << (written && !out.empty() ? out.string() : std::string("(not written)"));
        Logger->debug(ss.str());
    });
}

void NPCManager::pollUserIndex() {
    if (!indexFuture.valid()) {
        return;
    }
    if (indexFuture.wait_for(std::chrono::seconds(0)) != std::future_status::ready) {
        return;
    }
    indexFuture.get();
    indexFuture = std::future<void>();
}

void NPCManager::renderPawnIndexList() {
    static char search[128] = "";
    static bool loadedOnly = false;

    ensureIndexLoaded();
    pollUserIndex();

    renderPickerFilter("##npc_search", t("ui.npcs_presets.search"), characterSearch);
    ImGui::Checkbox(t("ui.npcs_presets.only_loaded"), &loadedOnly);

    const std::string filter = toLowerStr(characterSearch);
#ifdef SDK_TARGET_LE1
    // LE1's characters are not pawn classes, say so above the list
    ImGui::TextDisabled(t("ui.le1chars.hint"));
#endif

    static std::vector<PawnIndexRow> snapshot;
    static int seenVersion = -1;
    {
        std::lock_guard<std::mutex> lock(stateMtx);
        if (seenVersion != indexVersion) {
            seenVersion = indexVersion;
            snapshot = indexRows;
        }
    }

#ifdef SDK_TARGET_LE1
    // one list: LE1's hench_* characters and the pawn classes are the same thing to
    // the user, so both go in this table, spawned by the button below
    resolveCharacterGameNames();
    struct MergedRow {
            bool character = false;
            size_t index = 0;
            std::string label;
            std::string source;
            std::string exportName;
            bool resident = true;
    };
    static std::vector<MergedRow> merged;
    merged.clear();
    for (size_t i = 0; i < characterRows.size(); ++i) {
        MergedRow row;
        row.character = true;
        row.index = i;
        auto known = characterGameNames.find(characterRows[i].groupName);
        row.label = known != characterGameNames.end() ? known->second : characterRows[i].displayName;
        row.source = characterRows[i].groupName;
        row.exportName = characterRows[i].groupName;
        merged.push_back(row);
    }
    for (size_t i = 0; i < snapshot.size(); ++i) {
        MergedRow row;
        row.character = false;
        row.index = i;
        row.label = snapshot[i].displayName;
        row.source = snapshot[i].packageName;
        row.exportName = snapshot[i].exportName;
        row.resident = isPawnExportResident(snapshot[i].exportName);
        merged.push_back(row);
    }

    int shown = 0;
    {
        ChildScope list("##npc_index_scroll", ImVec2(0, 450.0f), true);

        if (list.open) {
            ImGui::BeginTable("##npc_index", 2, ImGuiTableFlags_SizingFixedFit | ImGuiTableFlags_SizingStretchProp | ImGuiTableFlags_RowBg);
            for (size_t r = 0; r < merged.size(); ++r) {
                const MergedRow& row = merged[r];
                if (loadedOnly && !row.resident) {
                    continue;
                }
                if (!filter.empty() && toLowerStr(row.label).find(filter) == std::string::npos && toLowerStr(row.source).find(filter) == std::string::npos &&
                    toLowerStr(row.exportName).find(filter) == std::string::npos) {
                    continue;
                }
                ImGui::TableNextRow();
                ImGui::TableSetColumnIndex(0);
                const bool selected = (int)r == selectedMergedRow;
                const std::string id = row.label + "##npc_merged_row_" + std::to_string(r);
                if (ImGui::Selectable(id.c_str(), selected)) {
                    selectedMergedRow = (int)r;
                }
                ImGui::TableSetColumnIndex(1);
                ImGui::AlignTextToFramePadding();
                // the package goes inline rather than in a tooltip: a tooltip opens a
                // window every frame it is hovered, which flickers while the panel is open
                ImGui::TextDisabled("%s  %s", row.resident ? ICON_FA_BOLT : ICON_FA_DOWNLOAD, row.source.c_str());
                ++shown;
            }
            ImGui::EndTable();
            if (shown == 0) {
                ImGui::TextDisabled(t("ui.npcs_presets.no_results"));
            }
        } // list.open
    } // scroll region

    const MergedRow* selected = (selectedMergedRow >= 0 && selectedMergedRow < (int)merged.size()) ? &merged[(size_t)selectedMergedRow] : nullptr;
    ImGui::Separator();
    if (selected) {
        ImGui::TextUnformatted(t("ui.animation_table.selected"));
        ImGui::SameLine();
        ImGui::Text("%s", selected->label.c_str());
    }
    ImGui::PushItemWidth(-100);
    ImGui::BeginDisabled(!selected);
    if (ImGui::Button((std::string(ICON_FA_PERSON " ") + t("ui.spawn")).c_str(), ImVec2(-1, 0))) {
        if (selected->character) {
            spawnCharacter(characterRows[selected->index]);
        } else {
            spawnFromIndexRow(snapshot[selected->index]);
        }
    }
    ImGui::PopItemWidth();
    ImGui::EndDisabled();
    return;
#endif

    // fixed 450px: the panel scrolls, so the list never needs to shrink to fit and
    // must not derive its height from the space left over, which went negative when
    int shownLegacy = 0;
    {
        ChildScope list("##npc_index_scroll", ImVec2(0, 450.0f), true);

        if (list.open) {
            ImGui::BeginTable("##npc_index", 2, ImGuiTableFlags_SizingFixedFit | ImGuiTableFlags_SizingStretchProp | ImGuiTableFlags_RowBg);
            for (size_t i = 0; i < snapshot.size(); ++i) {
                const PawnIndexRow& entry = snapshot[i];
                if (loadedOnly && !isPawnExportResident(entry.exportName)) {
                    continue;
                }
                if (!filter.empty() && toLowerStr(entry.displayName).find(filter) == std::string::npos &&
                    toLowerStr(entry.exportName).find(filter) == std::string::npos) {
                    continue;
                }

                ImGui::TableNextRow();
                ImGui::TableSetColumnIndex(0);
                const bool selected = (int)i == selectedIndexEntry;
                const std::string id = entry.displayName + "##npc_index_row_" + std::to_string(i);
                if (ImGui::Selectable(id.c_str(), selected)) {
                    selectedIndexEntry = (int)i;
                    selectedResidentClass.clear();
                }

                ImGui::TableSetColumnIndex(1);
                ImGui::AlignTextToFramePadding();
                // the package goes inline rather than in a tooltip: a tooltip opens a window
                // every frame it is hovered, which flickers while the panel is open
                ImGui::TextDisabled("%s  %s", isPawnExportResident(entry.exportName) ? ICON_FA_BOLT : ICON_FA_DOWNLOAD, entry.packageName.c_str());
                ++shownLegacy;
            }
            ImGui::EndTable();
            if (shownLegacy == 0) {
                ImGui::TextDisabled(t("ui.npcs_presets.no_results"));
            }
        } // list.open
    } // scroll region

    ImGui::Separator();
    if (selectedIndexEntry >= 0 && selectedIndexEntry < (int)snapshot.size()) {
        ImGui::TextUnformatted(t("ui.animation_table.selected"));
        ImGui::SameLine();
        ImGui::Text("%s", snapshot[selectedIndexEntry].displayName.c_str());
    }
    ImGui::PushItemWidth(-100);
    const bool haveSelection = (selectedIndexEntry >= 0 && selectedIndexEntry < (int)snapshot.size()) || !selectedResidentClass.empty();
    ImGui::BeginDisabled(!haveSelection);
    if (ImGui::Button((std::string(ICON_FA_PERSON " ") + t("ui.spawn")).c_str(), ImVec2(-1, 0))) {
        if (selectedIndexEntry >= 0 && selectedIndexEntry < (int)snapshot.size()) {
            spawnFromIndexRow(snapshot[selectedIndexEntry]);
        } else if (!selectedResidentClass.empty()) {
            PawnIndexRow row;
            row.exportName = selectedResidentClass;
            spawnFromIndexRow(row);
        }
    }
    ImGui::EndDisabled();
    ImGui::PopItemWidth();
}

#ifdef SDK_TARGET_LE1
// an LE1 character is a "hench_<name>" package of Bio_Appr_Character_* settings
// applied to a generic player pawn, not a pawn class of its own
namespace {

// the index has no NPC pawn class, so take the spawn class off a live non-player
// pawn in the level, that is how LE1 builds its own NPCs
USkeletalMeshComponent* bodyMeshOf(ABioPawn* pawn) {
    if (!pawn) {
        return nullptr;
    }
    if (pawn->Mesh && pawn->Mesh->SkeletalMesh) {
        return pawn->Mesh;
    }
    for (int i = 0; i < (int)pawn->m_aoMeshes.Count(); ++i) {
        USkeletalMeshComponent* mesh = pawn->m_aoMeshes.GetData()[i];
        if (mesh && mesh->SkeletalMesh) {
            return mesh;
        }
    }
    return nullptr;
}

// appearance property name -> pawn mesh slot
int slotForCharacterProperty(const std::string& rawName) {
    std::string n = toLowerStr(rawName);
    // most specific first, HeadGear contains Head and FacePlate contains Face
    if (n.find("headgear") != std::string::npos) {
        return PAWN_SLOT_HEADGEAR;
    }
    if (n.find("faceplate") != std::string::npos) {
        return PAWN_SLOT_FACEPLATE;
    }
    if (n.find("visor") != std::string::npos) {
        return PAWN_SLOT_VISOR;
    }
    if (n.find("hair") != std::string::npos) {
        return PAWN_SLOT_HAIR;
    }
    if (n.find("body") != std::string::npos) {
        return PAWN_SLOT_BODY;
    }
    if (n.find("head") != std::string::npos) {
        return PAWN_SLOT_HEAD;
    }
    return -1;
}

// MSVC forbids __try in anything that needs unwinding, so keep the raw read here
USkeletalMesh* readMeshProperty(UObject* obj, int32_t offset) {
    USkeletalMesh* mesh = nullptr;
    char* base = reinterpret_cast<char*>(obj);
    __try {
        mesh = *reinterpret_cast<USkeletalMesh**>(base + offset);
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return nullptr;
    }
    return mesh;
}

bool isCharacterSettingsClass(const UClass* cls, const std::string& groupName) {
    if (!cls) {
        return false;
    }
    const std::string path = FStringToUtf8(cls->GetFullName());
    if (path.rfind(groupName + ".", 0) != 0) {
        return false;
    }
    const std::string clsName = FStringToUtf8(cls->GetName());
    return clsName.find("Bio_Appr_Character") != std::string::npos || clsName.find("Appr_Character") != std::string::npos;
}

} // namespace

// game thread, every tick: the game re-asserts head gear on its own tick so a
// per-frame write loses the race. Request* is only a request, set the preference too
ABioPawn* NPCManager::selectedPawn(const std::string& pawnName) const {
    if (trackedPawn && isLiveObject(trackedPawn) && FStringToUtf8(trackedPawn->GetName()) == pawnName) {
        return trackedPawn;
    }
    if (pawnName.empty()) {
        return nullptr;
    }
    AActor* actor = Application::instance().engine().findActorByName(pawnName);
    if (actor && actor->IsA(ABioPawn::StaticClass()) && isLiveObject(actor)) {
        return static_cast<ABioPawn*>(actor);
    }
    return nullptr;
}

void NPCManager::applyHeadGearOverrides() {
    if (headGearWanted.empty()) {
        return;
    }
    for (auto it = headGearWanted.begin(); it != headGearWanted.end();) {
        ABioPawn* pawn = it->first;
        if (!pawn || !isLiveObject(pawn)) {
            it = headGearWanted.erase(it);
            continue;
        }
        const bool want[3] = {it->second[0], it->second[1], it->second[2]};
        // helmet, the preference is what persists, Request* is only a request
        pawn->SetHeadGearVisiblePreference(want[0] ? 1 : 0);
        pawn->OverrideHeadGearVisibility(want[0] ? 1 : 0);
        pawn->RequestHelmetVisible(want[0] ? 1 : 0);
        pawn->RequestVisorVisible(want[1] ? 1 : 0);
        pawn->RequestFacePlateVisible(want[2] ? 1 : 0);

        USkeletalMeshComponent* const parts[3] = {pawn->m_oHeadGearMesh, pawn->m_oVisorMesh, pawn->m_oFacePlateMesh};
        for (int i = 0; i < 3; ++i) {
            USkeletalMeshComponent* comp = parts[i];
            if (!comp) {
                continue;
            }
            const unsigned long target = want[i] ? 0 : 1;
            if (comp->HiddenGame != target) {
                comp->HiddenGame = target;
                comp->SetHidden(target != 0);
                Logger->debug(std::string("NPC headgear: '") + FStringToUtf8(pawn->GetName()) + "' part " + std::to_string(i) + " -> " +
                              (want[i] ? "shown" : "hidden") + " on " + FStringToUtf8(comp->GetName()));
            }
        }
        ++it;
    }
}

// LE1 names the packages by species (hench_krogan) and the character name lives on
// the pawn type as ActorGameName (Wrex, Garrus, ...). read it once the type is
// resident so the list reads as characters rather than species
void NPCManager::resolveCharacterGameNames() {
    for (CharacterIndexRow& row : characterRows) {
        if (characterGameNames.count(row.groupName)) {
            continue;
        }
        forEachOf<UBioPawnType>([&](UBioPawnType* pt) {
            if (!pt || FStringToUtf8(pt->GetName()) != row.groupName) {
                return;
            }
            const std::string gameName = FStringToUtf8(pt->ActorGameName);
            if (!gameName.empty()) {
                characterGameNames[row.groupName] = gameName;
            }
        });
    }
}

int NPCManager::applyCharacterAppearance(ABioPawn* pawn, const std::string& groupName, UBio_Appr_Character* appr) {
    if (!pawn) {
        return 0;
    }
    if (!appr) {
        Logger->debug("applyCharacterAppearance: '" + groupName + "' has no live UBio_Appr_Character to read");
        return 0;
    }

    // the character data is an object graph: Body.GetModel(armor, model) -> body,
    // Head[].m_oModelMesh -> head, Head[].m_aHairAppearance[] -> hair and
    // Body.m_oHeadGearAppearance -> visor and face plate
    USkeletalMesh* perSlot[PAWN_SLOT_COUNT] = {};
    int applied = 0;

    UBio_Appr_Character_Settings* settings = appr->m_oSettings;
    UBio_Appr_Character_Body* body = appr->Body;
    UBio_Appr_Character_Head* head = appr->Head.Count() > 0 ? appr->Head.GetData()[0] : nullptr;
    UBio_Appr_Character_HeadGear* headGear = body ? body->m_oHeadGearAppearance : nullptr;

    auto note = [&](const char* what, const USkeletalMesh* mesh) {
        Logger->debug("LE1 character property: " + groupName + " " + what + " = " + (mesh ? FStringToUtf8(mesh->GetFullPath()) : "(none)"));
    };

    if (body) {
        UBio_Appr_Character_Body_Settings* bs = settings ? settings->m_oBodySettings : nullptr;
        const int armorType = bs ? bs->m_eArmorType : 0;
        const int modelVar = bs ? bs->m_nModelVariant : 0;
        USkeletalMesh* mesh = body->GetModel(armorType, modelVar);
        note(("body[armor=" + std::to_string(armorType) + " model=" + std::to_string(modelVar) + "]").c_str(), mesh);
        perSlot[PAWN_SLOT_BODY] = mesh;
    } else {
        Logger->debug("LE1 character property: " + groupName + " has no Body");
    }

    if (head) {
        USkeletalMesh* mesh = head->m_oModelMesh;
        note("head", mesh);
        perSlot[PAWN_SLOT_HEAD] = mesh;

        if (head->m_aHairAppearance.Count() > 0) {
            UBio_Appr_Character_Hair* hair = head->m_aHairAppearance.GetData()[0];
            if (hair) {
                USkeletalMesh* hairMesh = hair->m_oModelMesh;
                note("hair", hairMesh);
                perSlot[PAWN_SLOT_HAIR] = hairMesh;
            }
        } else {
            Logger->debug("LE1 character property: " + groupName + " has no hair appearance");
        }
    } else {
        Logger->debug("LE1 character property: " + groupName + " has no Head");
    }

    if (headGear) {
        if (headGear->m_apVisorMesh.Count() > 0) {
            USkeletalMesh* visor = headGear->m_apVisorMesh.GetData()[0];
            note("visor", visor);
            perSlot[PAWN_SLOT_VISOR] = visor;
        }
        if (headGear->m_aFacePlateMeshSpec.Count() > 0) {
            USkeletalMesh* facePlate = headGear->m_aFacePlateMeshSpec.GetData()[0].m_pMesh;
            note("faceplate", facePlate);
            perSlot[PAWN_SLOT_FACEPLATE] = facePlate;
        }
    } else {
        Logger->debug("LE1 character property: " + groupName + " has no head gear");
    }

    for (int slot = 0; slot < PAWN_SLOT_COUNT; ++slot) {
        if (!perSlot[slot] || !isLiveObject(perSlot[slot])) {
            continue;
        }
        // no per-character pawn classes on LE1, so every pawn we make is a generic
        // BioPawn built for one bone topology. resizing a component leaves the pose
        // state on the old count, so only take a mesh that already fits
        USkeletalMeshComponent* comp = slotComponent(pawn, slot);
        if (comp && comp->SkeletalMesh) {
            const int have = comp->SkeletalMesh->RefSkeleton.Count();
            const int want = perSlot[slot]->RefSkeleton.Count();
            if (have > 0 && want > 0) {
                const int worst = (std::max)(have, want);
                const int diff = worst - (std::min)(have, want);
                if ((diff * 100) / worst > 20) {
                    std::ostringstream ss;
                    ss << "applyCharacterAppearance: '" << groupName << "' slot " << slot << " (" << t(slotLabelKey(slot)) << ") needs " << want
                       << " bones but '" << FStringToUtf8(pawn->GetName()) << "' already has " << have
                       << " - skipped, because LE1 cannot spawn a pawn built for this character and resizing it crashes the game";
                    Logger->debug(ss.str());
                    continue;
                }
            }
        }
        if (applySlot(pawn, slot, perSlot[slot])) {
            ++applied;
        }
    }

    std::ostringstream ss;
    ss << "applyCharacterAppearance: '" << groupName << "' -> '" << FStringToUtf8(appr->GetFullName()) << "' supplied " << applied << " slot(s) for '"
       << FStringToUtf8(pawn->GetName()) << "'";
    Logger->debug(ss.str());

    // a pawn only moves if something simulates, and a spawned one simulates from its
    // origin with nothing holding it up, so zero the mesh PhysicsWeight
    for (int i = 0; i < (int)pawn->m_aoMeshes.Count(); ++i) {
        USkeletalMeshComponent* mesh = pawn->m_aoMeshes.GetData()[i];
        if (!mesh) {
            continue;
        }
        if (mesh->PhysicsWeight != 0.0f) {
            Logger->debug("pawnCollision: '" + FStringToUtf8(pawn->GetName()) + "' mesh '" + FStringToUtf8(mesh->GetName()) +
                          "' had PhysicsWeight=" + std::to_string(mesh->PhysicsWeight) + ", zeroing it so the pawn is held by its collision cylinder");
            mesh->PhysicsWeight = 0.0f;
        }
    }

    return applied;
}

void NPCManager::spawnCharacter(const CharacterIndexRow& row) {
    const Transform spawnTransform = Application::instance().ui().getSpawnTransform();
    const std::string group = row.groupName;

    auto doSpawn = [this, group, spawnTransform](UBio_Appr_Character* appr) {
        Application::instance().engine().postGameThreadTask([this, group, spawnTransform, appr]() {
            // LE1's own pipeline: a UBioPawnType carries the class and the character
            // appearance and ABioSPGame::SpawnPawn builds the pawn from it. assigning
            // meshes by hand desyncs the bone topology and crashes
            // many types share one appearance object, the CDO among them, so take the
            // one named after the character and skip class defaults
            // the group name identifies the type exactly, matching on the appearance
            // is only a fallback since several types share one
            UBioPawnType* byGroup = nullptr;
            UBioPawnType* byAppearance = nullptr;
            int considered = 0;
            forEachOf<UBioPawnType>([&](UBioPawnType* pt) {
                if (!pt) {
                    return;
                }
                const std::string ptName = FStringToUtf8(pt->GetName());
                if (ptName.rfind("Default__", 0) == 0) {
                    return; // the class default names nothing and shares appearances
                }
                ++considered;
                if (!byGroup && ptName == group) {
                    byGroup = pt;
                }
                if (!byAppearance && pt->m_oAppearance == appr) {
                    byAppearance = pt;
                }
            });
            UBioPawnType* pawnType = byGroup ? byGroup : byAppearance;
            Logger->debug("spawnCharacter: '" + group + "' considered " + std::to_string(considered) + " UBioPawnType object(s), matched " +
                          (byGroup ? "by group name " : (byAppearance ? "by appearance " : "nothing ")) +
                          (pawnType ? FStringToUtf8(pawnType->GetFullName()) : std::string("(none)")));
            if (!pawnType) {
                return;
            }

            // SpawnPawn is the game's own pawn construction, so meshes, anim tree,
            // physics and collision come out consistent
            ABioSPGame* game = nullptr;
            forEachOf<ABioSPGame>([&](ABioSPGame* g) {
                if (!game && isLiveObject(g) && FStringToUtf8(g->GetName()).rfind("Default__", 0) != 0) {
                    game = g;
                }
            });
            if (!game) {
                Logger->debug("spawnCharacter: no live ABioSPGame to drive SpawnPawn for '" + group + "'");
                char buf[512];
                snprintf(buf, sizeof(buf), t("ui.le1chars.failed_no_pawn_class"), group.c_str());
                Application::instance().ui().toastManager.addToastNotification(buf, ToastTypeError, 4.0);
                return;
            }

            FVector loc;
            loc.X = spawnTransform.pos[0];
            loc.Y = spawnTransform.pos[1];
            loc.Z = spawnTransform.pos[2];
            FRotator rot;
            rot.Pitch = DegreesToUnrealRotationUnits(spawnTransform.rot[0]);
            rot.Yaw = DegreesToUnrealRotationUnits(spawnTransform.rot[1]);
            rot.Roll = DegreesToUnrealRotationUnits(spawnTransform.rot[2]);

            // TheActorType is resolved by name; try the object's path, then its bare
            // name, then the designer-facing ActorGameName, logging which one landed.
            const std::string fullPath = FStringToUtf8(pawnType->GetFullPath());
            const std::string shortName = FStringToUtf8(pawnType->GetName());
            Logger->debug("spawnCharacter: SpawnPawn via '" + FStringToUtf8(game->GetName()) + "' type='" + fullPath + "' gameName='" +
                          FStringToUtf8(pawnType->ActorGameName) +
                          "' cls=" + (pawnType->m_clsActor ? FStringToUtf8(pawnType->m_clsActor->GetFullName()) : "(null class)"));

            ABioPawn* spawned = nullptr;
            const std::string attempts[3] = {fullPath, shortName, FStringToUtf8(pawnType->ActorGameName)};
            for (int attempt = 0; attempt < 3 && !spawned; ++attempt) {
                if (attempts[attempt].empty()) {
                    continue;
                }
                spawned = game->SpawnPawn(FString(toWString(attempts[attempt]).c_str()), loc, rot, 0);
                Logger->debug("spawnCharacter: SpawnPawn('" + attempts[attempt] + "') -> " +
                              (spawned ? std::string("spawned ") + FStringToUtf8(spawned->GetName()) : std::string("null")));
            }
            if (!spawned) {
                Logger->debug("spawnCharacter: SpawnPawn returned null for '" + group + "'");
                return;
            }
            AActor* spawnedActor = spawned;

            const std::string pawnName = FStringToUtf8(spawned->GetName());
            Application::instance().engine().addSpawnedActor(spawned);
            {
                std::lock_guard<std::mutex> lock(pendingSelectMtx);
                pendingSelect = pawnName;
            }
            // track by pointer, SpawnPawn can hand back a name another actor in the
            // level already has, and then every name lookup finds the wrong pawn
            trackedPawn = spawned;
            trackedPawnName = pawnName;
            int sameName = 0;
            forEachOf<AActor>([&](AActor* other) {
                if (other && other != spawned && FStringToUtf8(other->GetName()) == pawnName) {
                    ++sameName;
                }
            });
            Logger->debug("spawnCharacter: '" + group + "' spawned '" + pawnName + "' as '" + FStringToUtf8(spawned->GetFullPath()) + "' class='" +
                          FStringToUtf8(spawned->Class->GetFullName()) + "'" +
                          (sameName > 0 ? " WARNING: " + std::to_string(sameName) + " other actor(s) share this name; tracked by pointer" : ""));
            // select it here, pendingSelect was drained by whichever panel rendered
            // first so the NPC panel kept showing the previous pawn
            Application::instance().ui().collectPawns();
            Application::instance().ui().selectActor(spawned);
            Logger->debug("spawnCharacter: selected '" + pawnName + "', now selected='" + Application::instance().ui().getSelectedPawnName() +
                          "' index=" + std::to_string(Application::instance().ui().pawnIndex()) + "'");
        });
    };

    const std::string packagePath = findPackagePath(row.sourcePackage);
    if (packagePath.empty()) {
        Logger->debug("spawnCharacter: no .pcc on disk for source '" + row.sourcePackage + "' (" + group + ")");
        char buf[512];
        snprintf(buf, sizeof(buf), t("ui.npcs_table.preset_package_missing"), row.sourcePackage.c_str());
        Application::instance().ui().toastManager.addToastNotification(buf, ToastTypeError, 4.0);
        return;
    }

    char loadingBuf[512];
    snprintf(loadingBuf, sizeof(loadingBuf), t("ui.le1chars.loading"), row.displayName.c_str());
    Application::instance().ui().toastManager.addToastNotification(loadingBuf, ToastTypeInfo, 3.0);
    Logger->debug("spawnCharacter: loading '" + packagePath + "' for '" + group + "'");

    // the character object arrives with the package, so diff what is already resident
    std::vector<UBio_Appr_Character*> before;
    forEachOf<UBio_Appr_Character>([&](UBio_Appr_Character* a) {
        if (a) {
            before.push_back(a);
        }
    });
    Logger->debug("spawnCharacter: " + std::to_string(before.size()) + " UBio_Appr_Character object(s) were already resident");

    Application::instance().engine().postPackageLoad(packagePath, [doSpawn, before]() {
        UBio_Appr_Character* loaded = nullptr;
        int fresh = 0;
        forEachOf<UBio_Appr_Character>([&](UBio_Appr_Character* a) {
            if (!a || std::find(before.begin(), before.end(), a) != before.end()) {
                return;
            }
            ++fresh;
            if (!loaded) {
                loaded = a;
            }
        });
        if (loaded) {
            Logger->debug("spawnCharacter: package load added " + std::to_string(fresh) + " appearance object(s), using '" +
                          FStringToUtf8(loaded->GetFullName()) + "'");
        } else {
            Logger->debug("spawnCharacter: package load added no UBio_Appr_Character object, the appearance cannot be applied");
        }
        doSpawn(loaded);
    });
}
#endif

void NPCManager::renderPawnPresets() {
    pollUserIndex();
    if (!ImGui::CollapsingHeader((std::string(ICON_FA_ADDRESS_BOOK " ") + t("ui.npcs_presets_title")).c_str())) {
        return;
    }
    ImGui::Indent();

    renderPawnIndexList();

    ImGui::Separator();
    if (indexScanRunning.load()) {
        const int total = indexScanTotal.load();
        const int done = indexScanDone.load();
        const float progress = total > 0 ? (float)done / (float)total : 0.0f;
        ImGui::ProgressBar(progress, ImVec2(-1, 0));
        ImGui::Text(t("ui.npcs_presets.scanning"), done, total, indexScanFound.load());
        if (ImGui::Button(t("ui.snapshots.cancel_button"))) {
            indexScanCancel = true;
        }
    } else {
        ImGui::TextUnformatted(t("ui.npcs_presets.index_tools"));
        ImGui::Checkbox(t("ui.npcs_presets.include_mods"), &indexIncludeMods);
        ImGui::SameLine();
        if (ImGui::Button((std::string(ICON_FA_FILE_EXPORT " ") + t("ui.npcs_presets.generate")).c_str())) {
            generateUserIndex();
        }
        ImGui::TextDisabled(t("ui.game_pkg_table.path"), userIndexPath().string().c_str());
    }

    ImGui::Unindent();
}

void NPCManager::renderPawnClassList() {
    if (selectedPawnClass.empty()) {
        for (const char* preferred : preferredPawnClasses) {
            if (std::find(pawnClasses.begin(), pawnClasses.end(), preferred) != pawnClasses.end()) {
                selectedPawnClass = preferred;
                break;
            }
        }
    }

    renderPickerFilter("##npc_class_filter", t("ui.npcs_table.filter_assets"), classListFilter);

    const std::string filter = toLowerStr(classListFilter);
    ChildScope child("##npc_class_list", ImVec2(0, 160), true);
    if (child.open) {
        int shown = 0;
        for (const std::string& cls : pawnClasses) {
            if (!filter.empty() && toLowerStr(cls).find(filter) == std::string::npos) {
                continue;
            }
            const std::string id = cls + "##npc_class";
            if (ImGui::Selectable(id.c_str(), cls == selectedPawnClass)) {
                selectedPawnClass = cls;
            }
            ++shown;
        }
        if (shown == 0) {
            ImGui::TextDisabled(t("ui.vfx_table.no_matches"));
        }
    }
}

void NPCManager::renderSpawnUI() {
    ZoneScopedN("NPC::renderSpawnUI");
    if (!ImGui::CollapsingHeader((std::string(ICON_FA_USER_ASTRONAUT " ") + t("ui.npcs")).c_str())) {
        return;
    }
    ImGui::Indent();

    if (!UObject::GObjObjects) {
        ImGui::TextDisabled(t("ui.spawn_table.sdk_glob_err"));
        ImGui::Unindent();
        return;
    }

    collectAssets(false);
    handlePendingSelect();

    renderPawnPresets();

    if (!ImGui::CollapsingHeader((std::string(ICON_FA_SLIDERS " ") + t("ui.npcs_table.advanced")).c_str(), ImGuiTreeNodeFlags_DefaultOpen)) {
        ImGui::Unindent();
        return;
    }
    ImGui::Indent();

    const std::function<void(const std::string&)> keep = [](const std::string&) {
    };

    if (ImGui::CollapsingHeader((std::string(ICON_FA_CUBE " ") + t("ui.npcs_table.meshes")).c_str())) {
        renderPickerTable(meshPickerRows(NPC_PICK_SPAWN_BODY), "##spawn_mesh_filter", t("ui.npcs_table.filter_assets"), meshPickerFilter,
                          [this, &keep](const PawnSlotRow& row, const std::string& filter) {
                              renderAssetPicker(row.picker, row.slot, skeletalMeshes, skeletalMeshesLower, keep, filter);
                          });
        ImGui::Checkbox((std::string(t("ui.npcs_table.show_all_assets")) + "##spawn").c_str(), &showAllAssets);
    }

    if (ImGui::CollapsingHeader((std::string(ICON_FA_MASK_FACE " ") + t("ui.npcs_table.face_and_effects")).c_str())) {
        renderPickerTable(facePickerRows(NPC_PICK_SPAWN_MORPH, NPC_PICK_SPAWN_CRUST), "##spawn_face_filter", t("ui.npcs_table.filter_assets"), facePickerFilter,
                          [this, &keep](const PawnSlotRow& row, const std::string& filter) {
                              if (row.picker == NPC_PICK_SPAWN_MORPH) {
                                  renderAssetPicker(row.picker, -1, morphFaces, morphFacesLower, keep, filter);
                                  return;
                              }
#ifndef SDK_TARGET_LE3
                              renderAssetPicker(row.picker, -1, crustTemplates, crustTemplatesLower, keep, filter);
#endif
                          });
#ifndef SDK_TARGET_LE3
        ImGui::TextDisabled(t("ui.npcs_table.crust_lifetime"));
        ImGui::SetNextItemWidth(-100);
        ImGui::DragFloat("##spawn_crust_lifetime", &spawnCrustLifeTime, 1.0f, 0.0f, 99999.0f, "%.0f");
#endif
    }

    if (ImGui::CollapsingHeader((std::string(ICON_FA_BOX_ARCHIVE " ") + t("ui.spawn_table.object_list")).c_str())) {
        renderPawnClassList();
    }

    ImGui::Separator();
    ImGui::Checkbox(t("ui.npcs_table.spawn_empty"), &spawnEmptyPawn);
    ImGui::SetNextItemWidth(-100);
    if (ImGui::Button((std::string(ICON_FA_PLUS " ") + t("ui.npcs_table.spawn_customized")).c_str(), ImVec2(-1, 0))) {
        PawnSpawnConfig config;
        config.classFullName = selectedPawnClass;
        config.assets[PAWN_SLOT_BODY] = picks[NPC_PICK_SPAWN_BODY];
        config.assets[PAWN_SLOT_HEAD] = picks[NPC_PICK_SPAWN_HEAD];
        config.assets[PAWN_SLOT_HAIR] = picks[NPC_PICK_SPAWN_HAIR];
        config.assets[PAWN_SLOT_HEADGEAR] = picks[NPC_PICK_SPAWN_HEADGEAR];
        config.assets[PAWN_SLOT_VISOR] = picks[NPC_PICK_SPAWN_VISOR];
        config.assets[PAWN_SLOT_FACEPLATE] = picks[NPC_PICK_SPAWN_FACEPLATE];
        config.morphHead = picks[NPC_PICK_SPAWN_MORPH];
#ifndef SDK_TARGET_LE3
        config.lifeCrust = picks[NPC_PICK_SPAWN_CRUST];
        config.lifeCrustLifeTime = spawnCrustLifeTime;
#endif
        const Transform spawnTransform = Application::instance().ui().getSpawnTransform();
        Application::instance().engine().postGameThreadTask([this, config, spawnTransform]() {
            spawnNPC(config, spawnTransform);
        });
    }

    ImGui::Unindent();
}

void NPCManager::renderSelectionUI() {
    ZoneScopedN("NPC::renderSelectionUI");
    if (!ImGui::CollapsingHeader((std::string(ICON_FA_MASK_FACE " ") + t("ui.npcs_selection")).c_str())) {
        return;
    }
    ImGui::Indent();

    // a spawned pawn selects itself, but pendingSelect was only drained by
    // renderSpawnUI, so the Selection tab kept showing the previous pawn
    handlePendingSelect();

    const std::string pawnName = Application::instance().ui().getSelectedPawnName();
#ifdef SDK_TARGET_LE1
    // SpawnPawn can return a name another actor already uses, prefer the tracked
    // instance over an ambiguous name lookup
    ABioPawn* pawn = selectedPawn(pawnName);
#else
    AActor* selected = pawnName.empty() ? nullptr : Application::instance().engine().findActorByName(pawnName);
    ABioPawn* pawn = (selected && selected->IsA(ABioPawn::StaticClass())) ? static_cast<ABioPawn*>(selected) : nullptr;
#endif

    if (!pawn) {
        ImGui::TextDisabled(t("ui.npcs_table.select_a_pawn"));
    } else {
#ifdef SDK_TARGET_LE1
        // armour spawns with the helmet/visor/face plate up, Wrex's shield for one.
        // keyed by pointer, a spawned pawn can share a name with another actor
        if (pawn) {
            if (!headGearWanted.count(pawn)) {
                headGearWanted[pawn] = std::array<bool, 3>{true, true, true};
                USkeletalMeshComponent* const parts[3] = {pawn->m_oHeadGearMesh, pawn->m_oVisorMesh, pawn->m_oFacePlateMesh};
                std::vector<std::string> partNames;
                for (USkeletalMeshComponent* part : parts) {
                    if (!part) {
                        partNames.push_back("(none)");
                        continue;
                    }
                    partNames.push_back(FStringToUtf8(part->GetName()) +
                                        (part->SkeletalMesh ? "[" + FStringToUtf8(part->SkeletalMesh->GetName()) + "]" : "[-]"));
                }
                std::ostringstream avail;
                avail << "NPC headgear: '" << FStringToUtf8(pawn->GetName()) << "' helmet=" << partNames[0] << " visor=" << partNames[1]
                      << " faceplate=" << partNames[2] << " accessories=" << pawn->m_aoAccessories.Count();
                Logger->debug(avail.str());
            }
            ImGui::Separator();
            ImGui::TextUnformatted(t("ui.le1chars.headgear"));
            static const char* const toggleKeys[3] = {"ui.le1chars.helmet", "ui.le1chars.visor", "ui.le1chars.faceplate"};
            for (int slot = 0; slot < 3; ++slot) {
                USkeletalMeshComponent* comp = slot == 0 ? pawn->m_oHeadGearMesh : (slot == 1 ? pawn->m_oVisorMesh : pawn->m_oFacePlateMesh);
                bool shown = headGearWanted[pawn][slot];
                if (comp && !comp->HiddenGame) {
                    shown = true;
                }
                const std::string id = std::string(t(toggleKeys[slot])) + "##hg" + std::to_string(slot) + "_" + FStringToUtf8(pawn->GetName());
                ImGui::BeginDisabled(comp == nullptr);
                if (ImGui::Checkbox(id.c_str(), &shown)) {
                    headGearWanted[pawn][slot] = shown;
                    if (slot == 0) {
                        pawn->SetHeadGearVisiblePreference(shown ? 1 : 0);
                        pawn->OverrideHeadGearVisibility(shown ? 1 : 0);
                        pawn->RequestHelmetVisible(shown ? 1 : 0);
                    } else if (slot == 1) {
                        pawn->RequestVisorVisible(shown ? 1 : 0);
                    } else {
                        pawn->RequestFacePlateVisible(shown ? 1 : 0);
                    }
                    Logger->debug(std::string("NPC headgear: '") + FStringToUtf8(pawn->GetName()) + "' " + toggleKeys[slot] + " -> " +
                                  (shown ? "shown" : "hidden") + (comp ? "" : " (no component on this pawn)"));
                }
                if (ImGui::IsItemHovered()) {
                    ImGui::SetTooltip("%s", comp ? t("ui.le1chars.headgear_hint") : t("ui.le1chars.headgear_absent"));
                }
                ImGui::EndDisabled();
            }
        }
#endif
        collectAssets(false);

        ImGui::Checkbox((std::string(t("ui.npcs_table.show_all_assets")) + "##live").c_str(), &showAllAssets);

        ImGui::Text(t("ui.npcs_table.target_pawn"));
        ImGui::SameLine();
        ImGui::Text("%s", pawnName.c_str());

        ImGui::Separator();
        if (ImGui::Button((std::string(ICON_FA_FILE_EXPORT " ") + t("ui.npcs_table.dump_pawn")).c_str())) {
            dumpPawn(pawn);
        }
        if (ImGui::CollapsingHeader((std::string(ICON_FA_SLIDERS " ") + t("ui.npcs_table.customization")).c_str())) {
            ImGui::Indent();
            renderLiveCustomization(pawn, pawnName);
            ImGui::Unindent();
        }
        renderSpawnedNpcList();
    }

    ImGui::Unindent();
}

void NPCManager::renderLiveCustomization(ABioPawn* pawn, const std::string& pawnName) {
    {

        // the components are re-checked here so a missing one is shown as unavailable
        // instead of silently doing nothing when clicked
        auto slotAvailable = [pawn](int slot) {
            return NPCManager::slotComponent(pawn, slot) != nullptr;
        };

        auto makeSlotApply = [this, &pawnName](int slot) {
            return std::function<void(const std::string&)>([this, &pawnName, slot](const std::string& path) {
                applySlotToPawn(pawnName, slot, path);
            });
        };

        // every slot renders in both panels: a class without the component is still
        // selectable, it just goes through the game's own fallback
        renderPickerTable(meshPickerRows(NPC_PICK_LIVE_BODY), "##live_mesh_filter", t("ui.npcs_table.filter_assets"), meshPickerFilter,
                          [this, &makeSlotApply, &slotAvailable](const PawnSlotRow& row, const std::string& filter) {
                              renderAssetPicker(row.picker, row.slot, skeletalMeshes, skeletalMeshesLower, makeSlotApply(row.slot), filter);
                              if (!slotAvailable(row.slot)) {
                                  ImGui::TextDisabled(t("ui.npcs_table.no_component_note"), t(row.labelKey));
                                  if (row.slot == PAWN_SLOT_HAIR) {
#ifndef SDK_TARGET_LE1
                                      ImGui::TextDisabled(t("ui.npcs_table.hair_merge_note"));
#endif
                                  }
                              }
                          });
        renderPickerTable(facePickerRows(NPC_PICK_LIVE_MORPH, NPC_PICK_LIVE_CRUST), "##live_face_filter", t("ui.npcs_table.filter_assets"), facePickerFilter,
                          [this, &pawnName](const PawnSlotRow& row, const std::string& filter) {
                              if (row.picker == NPC_PICK_LIVE_MORPH) {
                                  renderAssetPicker(
                                      row.picker, -1, morphFaces, morphFacesLower,
                                      [this, &pawnName](const std::string& path) {
                                          applyMorphHeadToPawn(pawnName, path);
                                      },
                                      filter);
                                  return;
                              }
#ifndef SDK_TARGET_LE3
                              renderAssetPicker(
                                  row.picker, -1, crustTemplates, crustTemplatesLower,
                                  [this, &pawnName](const std::string& path) {
                                      applyLifeCrustToPawn(pawnName, path, 9999.0f);
                                  },
                                  filter);
#endif
                          });

        renderMorphFacePanel(pawn, pawnName);
        renderMaterialsPanel(pawn);
    }
}

void NPCManager::renderSpawnedNpcList() {
    ImGui::Separator();
    ImGui::Text(t("ui.npcs_table.spawned_npcs"));
    {
        ChildScope child("##npc_spawned_list", ImVec2(0, 140), true);
        if (child.open) {
            const double now = ImGui::GetTime();
            if (now - spawnedNpcRefreshTime > 0.25) {
                spawnedNpcRefreshTime = now;
                // resolving each name walks GObjObjects, so this is throttled, and the
                // pawn filter is what keeps spawned lights and props out of the list
                spawnedNpcNames.clear();
                spawnedPawns.clear();
                // exact instances, not names: a name lookup would resolve to the wrong
                // pawn when LE1's SpawnPawn reused a name from the level
                for (AActor* actor : Application::instance().engine().spawnedActors()) {
                    if (actor && isLiveObject(actor) && actor->IsA(ABioPawn::StaticClass())) {
                        spawnedNpcNames.push_back(FStringToUtf8(actor->GetName()));
                        spawnedPawns.push_back(static_cast<ABioPawn*>(actor));
                    }
                }
            }

            if (spawnedNpcNames.empty()) {
                ImGui::TextDisabled(t("ui.npcs_table.no_spawned_npcs"));
            }
            for (size_t i = 0; i < spawnedNpcNames.size(); ++i) {
                const std::string& name = spawnedNpcNames[i];
                ImGui::Text("%s", name.c_str());
                ImGui::SameLine();
                ABioPawn* rowPawn = i < spawnedPawns.size() ? spawnedPawns[i] : nullptr;
                if (ImGui::Button((std::string(ICON_FA_CROSSHAIRS "##npc_sel_") + name + std::to_string(i)).c_str())) {
                    if (rowPawn && isLiveObject(rowPawn)) {
                        // select the instance, not whatever the name resolves to
                        trackedPawn = rowPawn;
                        trackedPawnName = name;
                        Application::instance().ui().selectActor(rowPawn);
                        Logger->debug("spawnedNpcList: selected '" + name + "' by pointer");
                    }
                }
                ImGui::SameLine();
                if (ImGui::Button((std::string(ICON_FA_FILE_EXPORT "##npc_dump_") + name + std::to_string(i)).c_str())) {
                    if (rowPawn && isLiveObject(rowPawn)) {
                        dumpPawn(rowPawn);
                    }
                }
                ImGui::SameLine();
                if (ImGui::Button((std::string(ICON_FA_TRASH_CAN "##npc_del_") + name + std::to_string(i)).c_str())) {
                    deleteNPCPawn(rowPawn);
                    spawnedNpcNames.erase(std::remove(spawnedNpcNames.begin(), spawnedNpcNames.end(), name), spawnedNpcNames.end());
                }
            }
        }
    }
}

